(window.ABDI_PAKET = window.ABDI_PAKET || {})["skd.tiu.perbandingan.1"] = [{"i":1697,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 2 cm. Skala peta 1 : 2.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 2 × 2.000.000 = 4.000.000 cm.\n2. 1 km = 100.000 cm, jadi 4.000.000 ÷ 100.000 = 40 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.000.000 berarti 1 cm di peta = 20 km, jadi 2 × 20 = 40 km.","o":["45","40","400","35","4"],"s":[0,1,0,0,0],"w":["Cek balik: 45 km ÷ 20 km per cm = 2,25 cm di peta, padahal jaraknya 2 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 35 km ÷ 20 km per cm = 1,75 cm di peta, padahal jaraknya 2 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm."],"h":"Hapus lima angka nol dari skala: 1 : 2.000.000 berarti 1 cm di peta mewakili 20 km."},{"i":1698,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 25 orang dalam 36 hari. Jika dikerjakan 3 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 25 orang × 36 hari = 900 hari-orang.\n2. Dengan 3 orang: 900 ÷ 3 = 300 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 25 × 36 = 3 × x, jadi x = 900 ÷ 3 = 300.","o":["4,32","301","302","299","300"],"s":[0,0,0,0,1],"w":["Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 3 orang × 301 hari = 903 hari-orang, padahal beban kerjanya 900 hari-orang.","Cek balik: 3 orang × 302 hari = 906 hari-orang, padahal beban kerjanya 900 hari-orang.","Cek balik: 3 orang × 299 hari = 897 hari-orang, padahal beban kerjanya 900 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1699,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 216 km dalam 3 jam. Dengan kecepatan yang sama, jarak 108 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 216 km ÷ 3 jam = 72 km/jam.\n2. Waktu = jarak ÷ kecepatan = 108 ÷ 72 = 1,5 jam.\nCara cepat: bandingkan jaraknya. 108 km adalah 0,5 kali 216 km, jadi waktunya 0,5 × 3 = 1,5 jam.","o":["6","2,5","2","1","1,5"],"s":[0,0,0,0,1],"w":["Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 2,5 jam × 72 km/jam = 180 km, padahal jaraknya 108 km.","Cek balik: 2 jam × 72 km/jam = 144 km, padahal jaraknya 108 km.","Cek balik: 1 jam × 72 km/jam = 72 km, padahal jaraknya 108 km.","Benar. Langkahnya ada di pembahasan."],"h":"Cari kecepatannya dulu: 216 km dibagi 3 jam."},{"i":1700,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 24 orang dalam 32 hari. Jika dikerjakan 3 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 24 orang × 32 hari = 768 hari-orang.\n2. Dengan 3 orang: 768 ÷ 3 = 256 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 24 × 32 = 3 × x, jadi x = 768 ÷ 3 = 256.","o":["257","256","4","258","255"],"s":[0,1,0,0,0],"w":["Cek balik: 3 orang × 257 hari = 771 hari-orang, padahal beban kerjanya 768 hari-orang.","Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 3 orang × 258 hari = 774 hari-orang, padahal beban kerjanya 768 hari-orang.","Cek balik: 3 orang × 255 hari = 765 hari-orang, padahal beban kerjanya 768 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1701,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 12 botol air mineral adalah Rp36.000. Dengan harga satuan yang sama, harga 24 botol air mineral adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu botol air mineral = Rp36.000 ÷ 12 = Rp3.000.\n2. Harga 24 botol air mineral = 24 × Rp3.000 = Rp72.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp36.000 × 2 = Rp72.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp72.000","Rp75.000","Rp78.000","Rp69.000","Rp18.000"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Kelebihan satu barang.","Ini harga 26 botol air mineral, bukan 24.","Kurang satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai."],"h":"Cari harga satu botol air mineral dulu: bagi Rp36.000 dengan 12."},{"i":1702,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 5 cm. Skala peta 1 : 1.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 5 × 1.000.000 = 5.000.000 cm.\n2. 1 km = 100.000 cm, jadi 5.000.000 ÷ 100.000 = 50 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.000.000 berarti 1 cm di peta = 10 km, jadi 5 × 10 = 50 km.","o":["50","500","55","5","45"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 55 km ÷ 10 km per cm = 5,5 cm di peta, padahal jaraknya 5 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 45 km ÷ 10 km per cm = 4,5 cm di peta, padahal jaraknya 5 cm."],"h":"Hapus lima angka nol dari skala: 1 : 1.000.000 berarti 1 cm di peta mewakili 10 km."},{"i":1703,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 2 buku tulis adalah Rp15.000. Dengan harga satuan yang sama, harga 24 buku tulis adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu buku tulis = Rp15.000 ÷ 2 = Rp7.500.\n2. Harga 24 buku tulis = 24 × Rp7.500 = Rp180.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp15.000 × 12 = Rp180.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp195.000","Rp1.250","Rp172.500","Rp180.000","Rp187.500"],"s":[0,0,0,1,0],"w":["Ini harga 26 buku tulis, bukan 24.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Kurang satu barang.","Benar. Langkahnya ada di pembahasan.","Kelebihan satu barang."],"h":"Cari harga satu buku tulis dulu: bagi Rp15.000 dengan 2."},{"i":1704,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 7 bungkus nasi adalah Rp143.500. Dengan harga satuan yang sama, harga 8 bungkus nasi adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu bungkus nasi = Rp143.500 ÷ 7 = Rp20.500.\n2. Harga 8 bungkus nasi = 8 × Rp20.500 = Rp164.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp143.500 × 8/7 = Rp164.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp184.500","Rp164.000","Rp143.500","Rp125.562,5","Rp205.000"],"s":[0,1,0,0,0],"w":["Kelebihan satu barang.","Benar. Langkahnya ada di pembahasan.","Kurang satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Ini harga 10 bungkus nasi, bukan 8."],"h":"Cari harga satu bungkus nasi dulu: bagi Rp143.500 dengan 7."},{"i":1705,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 150 km dalam 2 jam. Dengan kecepatan yang sama, jarak 450 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 150 km ÷ 2 jam = 75 km/jam.\n2. Waktu = jarak ÷ kecepatan = 450 ÷ 75 = 6 jam.\nCara cepat: bandingkan jaraknya. 450 km adalah 3 kali 150 km, jadi waktunya 3 × 2 = 6 jam.","o":["5","6","7","5,5","6,5"],"s":[0,1,0,0,0],"w":["Cek balik: 5 jam × 75 km/jam = 375 km, padahal jaraknya 450 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 7 jam × 75 km/jam = 525 km, padahal jaraknya 450 km.","Cek balik: 5,5 jam × 75 km/jam = 412,5 km, padahal jaraknya 450 km.","Cek balik: 6,5 jam × 75 km/jam = 487,5 km, padahal jaraknya 450 km."],"h":"Cari kecepatannya dulu: 150 km dibagi 2 jam."},{"i":1706,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 7 bungkus nasi adalah Rp98.000. Dengan harga satuan yang sama, harga 25 bungkus nasi adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu bungkus nasi = Rp98.000 ÷ 7 = Rp14.000.\n2. Harga 25 bungkus nasi = 25 × Rp14.000 = Rp350.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp98.000 × 25/7 = Rp350.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp336.000","Rp364.000","Rp378.000","Rp350.000","Rp27.440"],"s":[0,0,0,1,0],"w":["Kurang satu barang.","Kelebihan satu barang.","Ini harga 27 bungkus nasi, bukan 25.","Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai."],"h":"Cari harga satu bungkus nasi dulu: bagi Rp98.000 dengan 7."},{"i":1707,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 180 km dalam 3 jam. Dengan kecepatan yang sama, jarak 90 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 180 km ÷ 3 jam = 60 km/jam.\n2. Waktu = jarak ÷ kecepatan = 90 ÷ 60 = 1,5 jam.\nCara cepat: bandingkan jaraknya. 90 km adalah 0,5 kali 180 km, jadi waktunya 0,5 × 3 = 1,5 jam.","o":["1","1,5","2","6","2,5"],"s":[0,1,0,0,0],"w":["Cek balik: 1 jam × 60 km/jam = 60 km, padahal jaraknya 90 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 2 jam × 60 km/jam = 120 km, padahal jaraknya 90 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 2,5 jam × 60 km/jam = 150 km, padahal jaraknya 90 km."],"h":"Cari kecepatannya dulu: 180 km dibagi 3 jam."},{"i":1708,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 2 buku tulis adalah Rp10.000. Dengan harga satuan yang sama, harga 8 buku tulis adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu buku tulis = Rp10.000 ÷ 2 = Rp5.000.\n2. Harga 8 buku tulis = 8 × Rp5.000 = Rp40.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp10.000 × 4 = Rp40.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp40.000","Rp2.500","Rp45.000","Rp50.000","Rp35.000"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Kelebihan satu barang.","Ini harga 10 buku tulis, bukan 8.","Kurang satu barang."],"h":"Cari harga satu buku tulis dulu: bagi Rp10.000 dengan 2."},{"i":1709,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 270 km dalam 3 jam. Dengan kecepatan yang sama, jarak 135 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 270 km ÷ 3 jam = 90 km/jam.\n2. Waktu = jarak ÷ kecepatan = 135 ÷ 90 = 1,5 jam.\nCara cepat: bandingkan jaraknya. 135 km adalah 0,5 kali 270 km, jadi waktunya 0,5 × 3 = 1,5 jam.","o":["1,5","1","2,5","2","6"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 1 jam × 90 km/jam = 90 km, padahal jaraknya 135 km.","Cek balik: 2,5 jam × 90 km/jam = 225 km, padahal jaraknya 135 km.","Cek balik: 2 jam × 90 km/jam = 180 km, padahal jaraknya 135 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai."],"h":"Cari kecepatannya dulu: 270 km dibagi 3 jam."},{"i":1710,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 4 kaus adalah Rp302.000. Dengan harga satuan yang sama, harga 9 kaus adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kaus = Rp302.000 ÷ 4 = Rp75.500.\n2. Harga 9 kaus = 9 × Rp75.500 = Rp679.500.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp302.000 × 2,25 = Rp679.500. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp604.000","Rp679.500","Rp830.500","Rp755.000","Rp528.500"],"s":[0,1,0,0,0],"w":["Kurang satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 11 kaus, bukan 9.","Kelebihan satu barang.","Ini harga 7 kaus, bukan 9."],"h":"Cari harga satu kaus dulu: bagi Rp302.000 dengan 4."},{"i":1711,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 3 bungkus nasi adalah Rp58.500. Dengan harga satuan yang sama, harga 17 bungkus nasi adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu bungkus nasi = Rp58.500 ÷ 3 = Rp19.500.\n2. Harga 17 bungkus nasi = 17 × Rp19.500 = Rp331.500.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp58.500 × 17/3 = Rp331.500. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp331.500","Rp292.500","Rp370.500","Rp312.000","Rp351.000"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Ini harga 15 bungkus nasi, bukan 17.","Ini harga 19 bungkus nasi, bukan 17.","Kurang satu barang.","Kelebihan satu barang."],"h":"Cari harga satu bungkus nasi dulu: bagi Rp58.500 dengan 3."},{"i":1712,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 3,5 cm. Skala peta 1 : 2.500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 3,5 × 2.500.000 = 8.750.000 cm.\n2. 1 km = 100.000 cm, jadi 8.750.000 ÷ 100.000 = 87,5 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.500.000 berarti 1 cm di peta = 25 km, jadi 3,5 × 25 = 87,5 km.","o":["8,75","92,5","87,5","875","82,5"],"s":[0,0,1,0,0],"w":["Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 92,5 km ÷ 25 km per cm = 3,7 cm di peta, padahal jaraknya 3,5 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 82,5 km ÷ 25 km per cm = 3,3 cm di peta, padahal jaraknya 3,5 cm."],"h":"Hapus lima angka nol dari skala: 1 : 2.500.000 berarti 1 cm di peta mewakili 25 km."},{"i":1713,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 144 km dalam 2 jam. Dengan kecepatan yang sama, jarak 432 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 144 km ÷ 2 jam = 72 km/jam.\n2. Waktu = jarak ÷ kecepatan = 432 ÷ 72 = 6 jam.\nCara cepat: bandingkan jaraknya. 432 km adalah 3 kali 144 km, jadi waktunya 3 × 2 = 6 jam.","o":["7","6,5","5","5,5","6"],"s":[0,0,0,0,1],"w":["Cek balik: 7 jam × 72 km/jam = 504 km, padahal jaraknya 432 km.","Cek balik: 6,5 jam × 72 km/jam = 468 km, padahal jaraknya 432 km.","Cek balik: 5 jam × 72 km/jam = 360 km, padahal jaraknya 432 km.","Cek balik: 5,5 jam × 72 km/jam = 396 km, padahal jaraknya 432 km.","Benar. Langkahnya ada di pembahasan."],"h":"Cari kecepatannya dulu: 144 km dibagi 2 jam."},{"i":1714,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 11 kotak susu adalah Rp77.000. Dengan harga satuan yang sama, harga 20 kotak susu adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kotak susu = Rp77.000 ÷ 11 = Rp7.000.\n2. Harga 20 kotak susu = 20 × Rp7.000 = Rp140.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp77.000 × 20/11 = Rp140.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp140.000","Rp154.000","Rp147.000","Rp133.000","Rp42.350"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Ini harga 22 kotak susu, bukan 20.","Kelebihan satu barang.","Kurang satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai."],"h":"Cari harga satu kotak susu dulu: bagi Rp77.000 dengan 11."},{"i":1715,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 240 km dalam 3 jam. Dengan kecepatan yang sama, jarak 400 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 240 km ÷ 3 jam = 80 km/jam.\n2. Waktu = jarak ÷ kecepatan = 400 ÷ 80 = 5 jam.\nCara cepat: bandingkan jaraknya. 400 km adalah 5/3 kali 240 km, jadi waktunya 5/3 × 3 = 5 jam.","o":["1,8","6","5,5","4,5","5"],"s":[0,0,0,0,1],"w":["Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 6 jam × 80 km/jam = 480 km, padahal jaraknya 400 km.","Cek balik: 5,5 jam × 80 km/jam = 440 km, padahal jaraknya 400 km.","Cek balik: 4,5 jam × 80 km/jam = 360 km, padahal jaraknya 400 km.","Benar. Langkahnya ada di pembahasan."],"h":"Cari kecepatannya dulu: 240 km dibagi 3 jam."},{"i":1716,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 288 km dalam 4 jam. Dengan kecepatan yang sama, jarak 216 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 288 km ÷ 4 jam = 72 km/jam.\n2. Waktu = jarak ÷ kecepatan = 216 ÷ 72 = 3 jam.\nCara cepat: bandingkan jaraknya. 216 km adalah 0,75 kali 288 km, jadi waktunya 0,75 × 4 = 3 jam.","o":["2","3,5","2,5","4","3"],"s":[0,0,0,0,1],"w":["Cek balik: 2 jam × 72 km/jam = 144 km, padahal jaraknya 216 km.","Cek balik: 3,5 jam × 72 km/jam = 252 km, padahal jaraknya 216 km.","Cek balik: 2,5 jam × 72 km/jam = 180 km, padahal jaraknya 216 km.","Cek balik: 4 jam × 72 km/jam = 288 km, padahal jaraknya 216 km.","Benar. Langkahnya ada di pembahasan."],"h":"Cari kecepatannya dulu: 288 km dibagi 4 jam."},{"i":1717,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 3 cm. Skala peta 1 : 1.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 3 × 1.000.000 = 3.000.000 cm.\n2. 1 km = 100.000 cm, jadi 3.000.000 ÷ 100.000 = 30 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.000.000 berarti 1 cm di peta = 10 km, jadi 3 × 10 = 30 km.","o":["25","35","3","30","300"],"s":[0,0,0,1,0],"w":["Cek balik: 25 km ÷ 10 km per cm = 2,5 cm di peta, padahal jaraknya 3 cm.","Cek balik: 35 km ÷ 10 km per cm = 3,5 cm di peta, padahal jaraknya 3 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000."],"h":"Hapus lima angka nol dari skala: 1 : 1.000.000 berarti 1 cm di peta mewakili 10 km."},{"i":1718,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 120 km dalam 2 jam. Dengan kecepatan yang sama, jarak 180 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 120 km ÷ 2 jam = 60 km/jam.\n2. Waktu = jarak ÷ kecepatan = 180 ÷ 60 = 3 jam.\nCara cepat: bandingkan jaraknya. 180 km adalah 1,5 kali 120 km, jadi waktunya 1,5 × 2 = 3 jam.","o":["2","2,5","3","4","3,5"],"s":[0,0,1,0,0],"w":["Cek balik: 2 jam × 60 km/jam = 120 km, padahal jaraknya 180 km.","Cek balik: 2,5 jam × 60 km/jam = 150 km, padahal jaraknya 180 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 4 jam × 60 km/jam = 240 km, padahal jaraknya 180 km.","Cek balik: 3,5 jam × 60 km/jam = 210 km, padahal jaraknya 180 km."],"h":"Cari kecepatannya dulu: 120 km dibagi 2 jam."},{"i":1719,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 160 km dalam 2 jam. Dengan kecepatan yang sama, jarak 200 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 160 km ÷ 2 jam = 80 km/jam.\n2. Waktu = jarak ÷ kecepatan = 200 ÷ 80 = 2,5 jam.\nCara cepat: bandingkan jaraknya. 200 km adalah 1,25 kali 160 km, jadi waktunya 1,25 × 2 = 2,5 jam.","o":["3,5","2","1,6","3","2,5"],"s":[0,0,0,0,1],"w":["Cek balik: 3,5 jam × 80 km/jam = 280 km, padahal jaraknya 200 km.","Cek balik: 2 jam × 80 km/jam = 160 km, padahal jaraknya 200 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 3 jam × 80 km/jam = 240 km, padahal jaraknya 200 km.","Benar. Langkahnya ada di pembahasan."],"h":"Cari kecepatannya dulu: 160 km dibagi 2 jam."},{"i":1720,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 8 cm. Skala peta 1 : 2.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 8 × 2.000.000 = 16.000.000 cm.\n2. 1 km = 100.000 cm, jadi 16.000.000 ÷ 100.000 = 160 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.000.000 berarti 1 cm di peta = 20 km, jadi 8 × 20 = 160 km.","o":["1.600","16","155","165","160"],"s":[0,0,0,0,1],"w":["Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 155 km ÷ 20 km per cm = 7,75 cm di peta, padahal jaraknya 8 cm.","Cek balik: 165 km ÷ 20 km per cm = 8,25 cm di peta, padahal jaraknya 8 cm.","Benar. Langkahnya ada di pembahasan."],"h":"Hapus lima angka nol dari skala: 1 : 2.000.000 berarti 1 cm di peta mewakili 20 km."},{"i":1721,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 11 pulpen adalah Rp66.000. Dengan harga satuan yang sama, harga 5 pulpen adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu pulpen = Rp66.000 ÷ 11 = Rp6.000.\n2. Harga 5 pulpen = 5 × Rp6.000 = Rp30.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp66.000 × 5/11 = Rp30.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp30.000","Rp42.000","Rp36.000","Rp145.200","Rp24.000"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Ini harga 7 pulpen, bukan 5.","Kelebihan satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Kurang satu barang."],"h":"Cari harga satu pulpen dulu: bagi Rp66.000 dengan 11."},{"i":1722,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 10 roti adalah Rp55.000. Dengan harga satuan yang sama, harga 17 roti adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu roti = Rp55.000 ÷ 10 = Rp5.500.\n2. Harga 17 roti = 17 × Rp5.500 = Rp93.500.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp55.000 × 1,7 = Rp93.500. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp99.000","Rp82.500","Rp88.000","Rp93.500","Rp104.500"],"s":[0,0,0,1,0],"w":["Kelebihan satu barang.","Ini harga 15 roti, bukan 17.","Kurang satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 19 roti, bukan 17."],"h":"Cari harga satu roti dulu: bagi Rp55.000 dengan 10."},{"i":1723,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 400 km dalam 5 jam. Dengan kecepatan yang sama, jarak 240 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 400 km ÷ 5 jam = 80 km/jam.\n2. Waktu = jarak ÷ kecepatan = 240 ÷ 80 = 3 jam.\nCara cepat: bandingkan jaraknya. 240 km adalah 0,6 kali 400 km, jadi waktunya 0,6 × 5 = 3 jam.","o":["2","4","2,5","3,5","3"],"s":[0,0,0,0,1],"w":["Cek balik: 2 jam × 80 km/jam = 160 km, padahal jaraknya 240 km.","Cek balik: 4 jam × 80 km/jam = 320 km, padahal jaraknya 240 km.","Cek balik: 2,5 jam × 80 km/jam = 200 km, padahal jaraknya 240 km.","Cek balik: 3,5 jam × 80 km/jam = 280 km, padahal jaraknya 240 km.","Benar. Langkahnya ada di pembahasan."],"h":"Cari kecepatannya dulu: 400 km dibagi 5 jam."},{"i":1724,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 7 pulpen adalah Rp35.000. Dengan harga satuan yang sama, harga 10 pulpen adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu pulpen = Rp35.000 ÷ 7 = Rp5.000.\n2. Harga 10 pulpen = 10 × Rp5.000 = Rp50.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp35.000 × 10/7 = Rp50.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp55.000","Rp45.000","Rp24.500","Rp50.000","Rp60.000"],"s":[0,0,0,1,0],"w":["Kelebihan satu barang.","Kurang satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Benar. Langkahnya ada di pembahasan.","Ini harga 12 pulpen, bukan 10."],"h":"Cari harga satu pulpen dulu: bagi Rp35.000 dengan 7."},{"i":1725,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 22 orang dalam 24 hari. Jika dikerjakan 11 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 22 orang × 24 hari = 528 hari-orang.\n2. Dengan 11 orang: 528 ÷ 11 = 48 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 22 × 24 = 11 × x, jadi x = 528 ÷ 11 = 48.","o":["48","47","12","50","49"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 11 orang × 47 hari = 517 hari-orang, padahal beban kerjanya 528 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 11 orang × 50 hari = 550 hari-orang, padahal beban kerjanya 528 hari-orang.","Cek balik: 11 orang × 49 hari = 539 hari-orang, padahal beban kerjanya 528 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1726,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 6 cm. Skala peta 1 : 1.500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 6 × 1.500.000 = 9.000.000 cm.\n2. 1 km = 100.000 cm, jadi 9.000.000 ÷ 100.000 = 90 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.500.000 berarti 1 cm di peta = 15 km, jadi 6 × 15 = 90 km.","o":["90","900","95","9","85"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 95 km ÷ 15 km per cm = 19/3 cm di peta, padahal jaraknya 6 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 85 km ÷ 15 km per cm = 17/3 cm di peta, padahal jaraknya 6 cm."],"h":"Hapus lima angka nol dari skala: 1 : 1.500.000 berarti 1 cm di peta mewakili 15 km."},{"i":1727,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 5 roti adalah Rp57.500. Dengan harga satuan yang sama, harga 2 roti adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu roti = Rp57.500 ÷ 5 = Rp11.500.\n2. Harga 2 roti = 2 × Rp11.500 = Rp23.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp57.500 × 0,4 = Rp23.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp11.500","Rp34.500","Rp46.000","Rp143.750","Rp23.000"],"s":[0,0,0,0,1],"w":["Kurang satu barang.","Kelebihan satu barang.","Ini harga 4 roti, bukan 2.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Benar. Langkahnya ada di pembahasan."],"h":"Cari harga satu roti dulu: bagi Rp57.500 dengan 5."},{"i":1729,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 21 orang dalam 30 hari. Jika dikerjakan 5 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 21 orang × 30 hari = 630 hari-orang.\n2. Dengan 5 orang: 630 ÷ 5 = 126 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 21 × 30 = 5 × x, jadi x = 630 ÷ 5 = 126.","o":["125","126","124","128","127"],"s":[0,1,0,0,0],"w":["Cek balik: 5 orang × 125 hari = 625 hari-orang, padahal beban kerjanya 630 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 5 orang × 124 hari = 620 hari-orang, padahal beban kerjanya 630 hari-orang.","Cek balik: 5 orang × 128 hari = 640 hari-orang, padahal beban kerjanya 630 hari-orang.","Cek balik: 5 orang × 127 hari = 635 hari-orang, padahal beban kerjanya 630 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1730,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 6 cm. Skala peta 1 : 2.500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 6 × 2.500.000 = 15.000.000 cm.\n2. 1 km = 100.000 cm, jadi 15.000.000 ÷ 100.000 = 150 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.500.000 berarti 1 cm di peta = 25 km, jadi 6 × 25 = 150 km.","o":["145","150","15","155","1.500"],"s":[0,1,0,0,0],"w":["Cek balik: 145 km ÷ 25 km per cm = 5,8 cm di peta, padahal jaraknya 6 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 155 km ÷ 25 km per cm = 6,2 cm di peta, padahal jaraknya 6 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000."],"h":"Hapus lima angka nol dari skala: 1 : 2.500.000 berarti 1 cm di peta mewakili 25 km."},{"i":1731,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 2,5 cm. Skala peta 1 : 1.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 2,5 × 1.000.000 = 2.500.000 cm.\n2. 1 km = 100.000 cm, jadi 2.500.000 ÷ 100.000 = 25 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.000.000 berarti 1 cm di peta = 10 km, jadi 2,5 × 10 = 25 km.","o":["250","30","20","25","2,5"],"s":[0,0,0,1,0],"w":["Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 30 km ÷ 10 km per cm = 3 cm di peta, padahal jaraknya 2,5 cm.","Cek balik: 20 km ÷ 10 km per cm = 2 cm di peta, padahal jaraknya 2,5 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm."],"h":"Hapus lima angka nol dari skala: 1 : 1.000.000 berarti 1 cm di peta mewakili 10 km."},{"i":1732,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 2 botol air mineral adalah Rp7.000. Dengan harga satuan yang sama, harga 20 botol air mineral adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu botol air mineral = Rp7.000 ÷ 2 = Rp3.500.\n2. Harga 20 botol air mineral = 20 × Rp3.500 = Rp70.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp7.000 × 10 = Rp70.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp700","Rp66.500","Rp73.500","Rp70.000","Rp77.000"],"s":[0,0,0,1,0],"w":["Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Kurang satu barang.","Kelebihan satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 22 botol air mineral, bukan 20."],"h":"Cari harga satu botol air mineral dulu: bagi Rp7.000 dengan 2."},{"i":1733,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 3,5 cm. Skala peta 1 : 1.500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 3,5 × 1.500.000 = 5.250.000 cm.\n2. 1 km = 100.000 cm, jadi 5.250.000 ÷ 100.000 = 52,5 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.500.000 berarti 1 cm di peta = 15 km, jadi 3,5 × 15 = 52,5 km.","o":["525","47,5","52,5","57,5","5,25"],"s":[0,0,1,0,0],"w":["Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 47,5 km ÷ 15 km per cm = 19/6 cm di peta, padahal jaraknya 3,5 cm.","Benar. Langkahnya ada di pembahasan.","Cek balik: 57,5 km ÷ 15 km per cm = 23/6 cm di peta, padahal jaraknya 3,5 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm."],"h":"Hapus lima angka nol dari skala: 1 : 1.500.000 berarti 1 cm di peta mewakili 15 km."},{"i":1734,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 22 orang dalam 20 hari. Jika dikerjakan 8 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 22 orang × 20 hari = 440 hari-orang.\n2. Dengan 8 orang: 440 ÷ 8 = 55 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 22 × 20 = 8 × x, jadi x = 440 ÷ 8 = 55.","o":["55","54","57","53","56"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 8 orang × 54 hari = 432 hari-orang, padahal beban kerjanya 440 hari-orang.","Cek balik: 8 orang × 57 hari = 456 hari-orang, padahal beban kerjanya 440 hari-orang.","Cek balik: 8 orang × 53 hari = 424 hari-orang, padahal beban kerjanya 440 hari-orang.","Cek balik: 8 orang × 56 hari = 448 hari-orang, padahal beban kerjanya 440 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1736,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 11 orang dalam 15 hari. Jika dikerjakan 3 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 11 orang × 15 hari = 165 hari-orang.\n2. Dengan 3 orang: 165 ÷ 3 = 55 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 11 × 15 = 3 × x, jadi x = 165 ÷ 3 = 55.","o":["57","55","53","56","54"],"s":[0,1,0,0,0],"w":["Cek balik: 3 orang × 57 hari = 171 hari-orang, padahal beban kerjanya 165 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 3 orang × 53 hari = 159 hari-orang, padahal beban kerjanya 165 hari-orang.","Cek balik: 3 orang × 56 hari = 168 hari-orang, padahal beban kerjanya 165 hari-orang.","Cek balik: 3 orang × 54 hari = 162 hari-orang, padahal beban kerjanya 165 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1737,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 3,5 cm. Skala peta 1 : 500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 3,5 × 500.000 = 1.750.000 cm.\n2. 1 km = 100.000 cm, jadi 1.750.000 ÷ 100.000 = 17,5 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 500.000 berarti 1 cm di peta = 5 km, jadi 3,5 × 5 = 17,5 km.","o":["22,5","17,5","12,5","1,75","175"],"s":[0,1,0,0,0],"w":["Cek balik: 22,5 km ÷ 5 km per cm = 4,5 cm di peta, padahal jaraknya 3,5 cm.","Benar. Langkahnya ada di pembahasan.","Cek balik: 12,5 km ÷ 5 km per cm = 2,5 cm di peta, padahal jaraknya 3,5 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000."],"h":"Hapus lima angka nol dari skala: 1 : 500.000 berarti 1 cm di peta mewakili 5 km."},{"i":1738,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 4 buku tulis adalah Rp26.000. Dengan harga satuan yang sama, harga 23 buku tulis adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu buku tulis = Rp26.000 ÷ 4 = Rp6.500.\n2. Harga 23 buku tulis = 23 × Rp6.500 = Rp149.500.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp26.000 × 5,75 = Rp149.500. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp136.500","Rp162.500","Rp149.500","Rp156.000","Rp143.000"],"s":[0,0,1,0,0],"w":["Ini harga 21 buku tulis, bukan 23.","Ini harga 25 buku tulis, bukan 23.","Benar. Langkahnya ada di pembahasan.","Kelebihan satu barang.","Kurang satu barang."],"h":"Cari harga satu buku tulis dulu: bagi Rp26.000 dengan 4."},{"i":1739,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 120 km dalam 2 jam. Dengan kecepatan yang sama, jarak 90 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 120 km ÷ 2 jam = 60 km/jam.\n2. Waktu = jarak ÷ kecepatan = 90 ÷ 60 = 1,5 jam.\nCara cepat: bandingkan jaraknya. 90 km adalah 0,75 kali 120 km, jadi waktunya 0,75 × 2 = 1,5 jam.","o":["1,5","2,5","2","1","0,5"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 2,5 jam × 60 km/jam = 150 km, padahal jaraknya 90 km.","Cek balik: 2 jam × 60 km/jam = 120 km, padahal jaraknya 90 km.","Cek balik: 1 jam × 60 km/jam = 60 km, padahal jaraknya 90 km.","Cek balik: 0,5 jam × 60 km/jam = 30 km, padahal jaraknya 90 km."],"h":"Cari kecepatannya dulu: 120 km dibagi 2 jam."},{"i":1740,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 16 orang dalam 6 hari. Jika dikerjakan 3 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 16 orang × 6 hari = 96 hari-orang.\n2. Dengan 3 orang: 96 ÷ 3 = 32 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 16 × 6 = 3 × x, jadi x = 96 ÷ 3 = 32.","o":["34","33","31","30","32"],"s":[0,0,0,0,1],"w":["Cek balik: 3 orang × 34 hari = 102 hari-orang, padahal beban kerjanya 96 hari-orang.","Cek balik: 3 orang × 33 hari = 99 hari-orang, padahal beban kerjanya 96 hari-orang.","Cek balik: 3 orang × 31 hari = 93 hari-orang, padahal beban kerjanya 96 hari-orang.","Cek balik: 3 orang × 30 hari = 90 hari-orang, padahal beban kerjanya 96 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1741,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 180 km dalam 2 jam. Dengan kecepatan yang sama, jarak 225 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 180 km ÷ 2 jam = 90 km/jam.\n2. Waktu = jarak ÷ kecepatan = 225 ÷ 90 = 2,5 jam.\nCara cepat: bandingkan jaraknya. 225 km adalah 1,25 kali 180 km, jadi waktunya 1,25 × 2 = 2,5 jam.","o":["3,5","3","1,6","2,5","2"],"s":[0,0,0,1,0],"w":["Cek balik: 3,5 jam × 90 km/jam = 315 km, padahal jaraknya 225 km.","Cek balik: 3 jam × 90 km/jam = 270 km, padahal jaraknya 225 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Benar. Langkahnya ada di pembahasan.","Cek balik: 2 jam × 90 km/jam = 180 km, padahal jaraknya 225 km."],"h":"Cari kecepatannya dulu: 180 km dibagi 2 jam."},{"i":1742,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 2,5 cm. Skala peta 1 : 2.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 2,5 × 2.000.000 = 5.000.000 cm.\n2. 1 km = 100.000 cm, jadi 5.000.000 ÷ 100.000 = 50 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.000.000 berarti 1 cm di peta = 20 km, jadi 2,5 × 20 = 50 km.","o":["50","45","500","55","5"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 45 km ÷ 20 km per cm = 2,25 cm di peta, padahal jaraknya 2,5 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 55 km ÷ 20 km per cm = 2,75 cm di peta, padahal jaraknya 2,5 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm."],"h":"Hapus lima angka nol dari skala: 1 : 2.000.000 berarti 1 cm di peta mewakili 20 km."},{"i":1743,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 200 km dalam 4 jam. Dengan kecepatan yang sama, jarak 300 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 200 km ÷ 4 jam = 50 km/jam.\n2. Waktu = jarak ÷ kecepatan = 300 ÷ 50 = 6 jam.\nCara cepat: bandingkan jaraknya. 300 km adalah 1,5 kali 200 km, jadi waktunya 1,5 × 4 = 6 jam.","o":["6","5","6,5","5,5","7"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 5 jam × 50 km/jam = 250 km, padahal jaraknya 300 km.","Cek balik: 6,5 jam × 50 km/jam = 325 km, padahal jaraknya 300 km.","Cek balik: 5,5 jam × 50 km/jam = 275 km, padahal jaraknya 300 km.","Cek balik: 7 jam × 50 km/jam = 350 km, padahal jaraknya 300 km."],"h":"Cari kecepatannya dulu: 200 km dibagi 4 jam."},{"i":1744,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 12 bungkus nasi adalah Rp276.000. Dengan harga satuan yang sama, harga 10 bungkus nasi adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu bungkus nasi = Rp276.000 ÷ 12 = Rp23.000.\n2. Harga 10 bungkus nasi = 10 × Rp23.000 = Rp230.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp276.000 × 5/6 = Rp230.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp253.000","Rp276.000","Rp207.000","Rp331.200","Rp230.000"],"s":[0,0,0,0,1],"w":["Kelebihan satu barang.","Ini harga 12 bungkus nasi, bukan 10.","Kurang satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Benar. Langkahnya ada di pembahasan."],"h":"Cari harga satu bungkus nasi dulu: bagi Rp276.000 dengan 12."},{"i":1745,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 9 kotak susu adalah Rp81.000. Dengan harga satuan yang sama, harga 11 kotak susu adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kotak susu = Rp81.000 ÷ 9 = Rp9.000.\n2. Harga 11 kotak susu = 11 × Rp9.000 = Rp99.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp81.000 × 11/9 = Rp99.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp81.000","Rp108.000","Rp90.000","Rp99.000","Rp117.000"],"s":[0,0,0,1,0],"w":["Ini harga 9 kotak susu, bukan 11.","Kelebihan satu barang.","Kurang satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 13 kotak susu, bukan 11."],"h":"Cari harga satu kotak susu dulu: bagi Rp81.000 dengan 9."},{"i":1746,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 7,5 cm. Skala peta 1 : 3.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 7,5 × 3.000.000 = 22.500.000 cm.\n2. 1 km = 100.000 cm, jadi 22.500.000 ÷ 100.000 = 225 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 3.000.000 berarti 1 cm di peta = 30 km, jadi 7,5 × 30 = 225 km.","o":["220","225","230","2.250","22,5"],"s":[0,1,0,0,0],"w":["Cek balik: 220 km ÷ 30 km per cm = 22/3 cm di peta, padahal jaraknya 7,5 cm.","Benar. Langkahnya ada di pembahasan.","Cek balik: 230 km ÷ 30 km per cm = 23/3 cm di peta, padahal jaraknya 7,5 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm."],"h":"Hapus lima angka nol dari skala: 1 : 3.000.000 berarti 1 cm di peta mewakili 30 km."},{"i":1747,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 225 km dalam 3 jam. Dengan kecepatan yang sama, jarak 450 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 225 km ÷ 3 jam = 75 km/jam.\n2. Waktu = jarak ÷ kecepatan = 450 ÷ 75 = 6 jam.\nCara cepat: bandingkan jaraknya. 450 km adalah 2 kali 225 km, jadi waktunya 2 × 3 = 6 jam.","o":["7","1,5","5,5","6,5","6"],"s":[0,0,0,0,1],"w":["Cek balik: 7 jam × 75 km/jam = 525 km, padahal jaraknya 450 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 5,5 jam × 75 km/jam = 412,5 km, padahal jaraknya 450 km.","Cek balik: 6,5 jam × 75 km/jam = 487,5 km, padahal jaraknya 450 km.","Benar. Langkahnya ada di pembahasan."],"h":"Cari kecepatannya dulu: 225 km dibagi 3 jam."},{"i":1748,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 2 cm. Skala peta 1 : 3.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 2 × 3.000.000 = 6.000.000 cm.\n2. 1 km = 100.000 cm, jadi 6.000.000 ÷ 100.000 = 60 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 3.000.000 berarti 1 cm di peta = 30 km, jadi 2 × 30 = 60 km.","o":["55","60","6","600","65"],"s":[0,1,0,0,0],"w":["Cek balik: 55 km ÷ 30 km per cm = 11/6 cm di peta, padahal jaraknya 2 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 65 km ÷ 30 km per cm = 13/6 cm di peta, padahal jaraknya 2 cm."],"h":"Hapus lima angka nol dari skala: 1 : 3.000.000 berarti 1 cm di peta mewakili 30 km."},{"i":1750,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 8 cm. Skala peta 1 : 2.500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 8 × 2.500.000 = 20.000.000 cm.\n2. 1 km = 100.000 cm, jadi 20.000.000 ÷ 100.000 = 200 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.500.000 berarti 1 cm di peta = 25 km, jadi 8 × 25 = 200 km.","o":["195","205","200","20","2.000"],"s":[0,0,1,0,0],"w":["Cek balik: 195 km ÷ 25 km per cm = 7,8 cm di peta, padahal jaraknya 8 cm.","Cek balik: 205 km ÷ 25 km per cm = 8,2 cm di peta, padahal jaraknya 8 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000."],"h":"Hapus lima angka nol dari skala: 1 : 2.500.000 berarti 1 cm di peta mewakili 25 km."},{"i":1751,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 4 cm. Skala peta 1 : 1.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 4 × 1.000.000 = 4.000.000 cm.\n2. 1 km = 100.000 cm, jadi 4.000.000 ÷ 100.000 = 40 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.000.000 berarti 1 cm di peta = 10 km, jadi 4 × 10 = 40 km.","o":["40","35","45","4","400"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 35 km ÷ 10 km per cm = 3,5 cm di peta, padahal jaraknya 4 cm.","Cek balik: 45 km ÷ 10 km per cm = 4,5 cm di peta, padahal jaraknya 4 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000."],"h":"Hapus lima angka nol dari skala: 1 : 1.000.000 berarti 1 cm di peta mewakili 10 km."},{"i":1752,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 5 cm. Skala peta 1 : 500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 5 × 500.000 = 2.500.000 cm.\n2. 1 km = 100.000 cm, jadi 2.500.000 ÷ 100.000 = 25 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 500.000 berarti 1 cm di peta = 5 km, jadi 5 × 5 = 25 km.","o":["30","2,5","25","20","250"],"s":[0,0,1,0,0],"w":["Cek balik: 30 km ÷ 5 km per cm = 6 cm di peta, padahal jaraknya 5 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Benar. Langkahnya ada di pembahasan.","Cek balik: 20 km ÷ 5 km per cm = 4 cm di peta, padahal jaraknya 5 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000."],"h":"Hapus lima angka nol dari skala: 1 : 500.000 berarti 1 cm di peta mewakili 5 km."},{"i":1753,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 14 orang dalam 36 hari. Jika dikerjakan 8 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 14 orang × 36 hari = 504 hari-orang.\n2. Dengan 8 orang: 504 ÷ 8 = 63 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 14 × 36 = 8 × x, jadi x = 504 ÷ 8 = 63.","o":["65","63","61","62","64"],"s":[0,1,0,0,0],"w":["Cek balik: 8 orang × 65 hari = 520 hari-orang, padahal beban kerjanya 504 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 8 orang × 61 hari = 488 hari-orang, padahal beban kerjanya 504 hari-orang.","Cek balik: 8 orang × 62 hari = 496 hari-orang, padahal beban kerjanya 504 hari-orang.","Cek balik: 8 orang × 64 hari = 512 hari-orang, padahal beban kerjanya 504 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1755,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 180 km dalam 3 jam. Dengan kecepatan yang sama, jarak 360 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 180 km ÷ 3 jam = 60 km/jam.\n2. Waktu = jarak ÷ kecepatan = 360 ÷ 60 = 6 jam.\nCara cepat: bandingkan jaraknya. 360 km adalah 2 kali 180 km, jadi waktunya 2 × 3 = 6 jam.","o":["6","6,5","5,5","7","1,5"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 6,5 jam × 60 km/jam = 390 km, padahal jaraknya 360 km.","Cek balik: 5,5 jam × 60 km/jam = 330 km, padahal jaraknya 360 km.","Cek balik: 7 jam × 60 km/jam = 420 km, padahal jaraknya 360 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai."],"h":"Cari kecepatannya dulu: 180 km dibagi 3 jam."},{"i":1756,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 7 kotak susu adalah Rp59.500. Dengan harga satuan yang sama, harga 16 kotak susu adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kotak susu = Rp59.500 ÷ 7 = Rp8.500.\n2. Harga 16 kotak susu = 16 × Rp8.500 = Rp136.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp59.500 × 16/7 = Rp136.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp127.500","Rp26.031,25","Rp136.000","Rp144.500","Rp153.000"],"s":[0,0,1,0,0],"w":["Kurang satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Benar. Langkahnya ada di pembahasan.","Kelebihan satu barang.","Ini harga 18 kotak susu, bukan 16."],"h":"Cari harga satu kotak susu dulu: bagi Rp59.500 dengan 7."},{"i":1757,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 8 kotak susu adalah Rp40.000. Dengan harga satuan yang sama, harga 21 kotak susu adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kotak susu = Rp40.000 ÷ 8 = Rp5.000.\n2. Harga 21 kotak susu = 21 × Rp5.000 = Rp105.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp40.000 × 2,625 = Rp105.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp110.000","Rp95.000","Rp115.000","Rp105.000","Rp100.000"],"s":[0,0,0,1,0],"w":["Kelebihan satu barang.","Ini harga 19 kotak susu, bukan 21.","Ini harga 23 kotak susu, bukan 21.","Benar. Langkahnya ada di pembahasan.","Kurang satu barang."],"h":"Cari harga satu kotak susu dulu: bagi Rp40.000 dengan 8."},{"i":1758,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 23 orang dalam 36 hari. Jika dikerjakan 3 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 23 orang × 36 hari = 828 hari-orang.\n2. Dengan 3 orang: 828 ÷ 3 = 276 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 23 × 36 = 3 × x, jadi x = 828 ÷ 3 = 276.","o":["276","274","278","277","275"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 3 orang × 274 hari = 822 hari-orang, padahal beban kerjanya 828 hari-orang.","Cek balik: 3 orang × 278 hari = 834 hari-orang, padahal beban kerjanya 828 hari-orang.","Cek balik: 3 orang × 277 hari = 831 hari-orang, padahal beban kerjanya 828 hari-orang.","Cek balik: 3 orang × 275 hari = 825 hari-orang, padahal beban kerjanya 828 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1759,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 27 orang dalam 25 hari. Jika dikerjakan 9 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 27 orang × 25 hari = 675 hari-orang.\n2. Dengan 9 orang: 675 ÷ 9 = 75 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 27 × 25 = 9 × x, jadi x = 675 ÷ 9 = 75.","o":["77","73","76","74","75"],"s":[0,0,0,0,1],"w":["Cek balik: 9 orang × 77 hari = 693 hari-orang, padahal beban kerjanya 675 hari-orang.","Cek balik: 9 orang × 73 hari = 657 hari-orang, padahal beban kerjanya 675 hari-orang.","Cek balik: 9 orang × 76 hari = 684 hari-orang, padahal beban kerjanya 675 hari-orang.","Cek balik: 9 orang × 74 hari = 666 hari-orang, padahal beban kerjanya 675 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1760,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 216 km dalam 3 jam. Dengan kecepatan yang sama, jarak 288 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 216 km ÷ 3 jam = 72 km/jam.\n2. Waktu = jarak ÷ kecepatan = 288 ÷ 72 = 4 jam.\nCara cepat: bandingkan jaraknya. 288 km adalah 4/3 kali 216 km, jadi waktunya 4/3 × 3 = 4 jam.","o":["5","2,25","4","4,5","3,5"],"s":[0,0,1,0,0],"w":["Cek balik: 5 jam × 72 km/jam = 360 km, padahal jaraknya 288 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Benar. Langkahnya ada di pembahasan.","Cek balik: 4,5 jam × 72 km/jam = 324 km, padahal jaraknya 288 km.","Cek balik: 3,5 jam × 72 km/jam = 252 km, padahal jaraknya 288 km."],"h":"Cari kecepatannya dulu: 216 km dibagi 3 jam."},{"i":1761,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 8 kaus adalah Rp508.000. Dengan harga satuan yang sama, harga 23 kaus adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kaus = Rp508.000 ÷ 8 = Rp63.500.\n2. Harga 23 kaus = 23 × Rp63.500 = Rp1.460.500.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp508.000 × 2,875 = Rp1.460.500. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp1.587.500","Rp1.460.500","Rp1.397.000","Rp1.524.000","Rp1.333.500"],"s":[0,1,0,0,0],"w":["Ini harga 25 kaus, bukan 23.","Benar. Langkahnya ada di pembahasan.","Kurang satu barang.","Kelebihan satu barang.","Ini harga 21 kaus, bukan 23."],"h":"Cari harga satu kaus dulu: bagi Rp508.000 dengan 8."},{"i":1762,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 5 bungkus nasi adalah Rp87.500. Dengan harga satuan yang sama, harga 13 bungkus nasi adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu bungkus nasi = Rp87.500 ÷ 5 = Rp17.500.\n2. Harga 13 bungkus nasi = 13 × Rp17.500 = Rp227.500.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp87.500 × 2,6 = Rp227.500. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp210.000","Rp192.500","Rp245.000","Rp262.500","Rp227.500"],"s":[0,0,0,0,1],"w":["Kurang satu barang.","Ini harga 11 bungkus nasi, bukan 13.","Kelebihan satu barang.","Ini harga 15 bungkus nasi, bukan 13.","Benar. Langkahnya ada di pembahasan."],"h":"Cari harga satu bungkus nasi dulu: bagi Rp87.500 dengan 5."},{"i":1763,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 5 kotak susu adalah Rp25.000. Dengan harga satuan yang sama, harga 11 kotak susu adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kotak susu = Rp25.000 ÷ 5 = Rp5.000.\n2. Harga 11 kotak susu = 11 × Rp5.000 = Rp55.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp25.000 × 2,2 = Rp55.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp60.000","Rp65.000","Rp55.000","Rp45.000","Rp50.000"],"s":[0,0,1,0,0],"w":["Kelebihan satu barang.","Ini harga 13 kotak susu, bukan 11.","Benar. Langkahnya ada di pembahasan.","Ini harga 9 kotak susu, bukan 11.","Kurang satu barang."],"h":"Cari harga satu kotak susu dulu: bagi Rp25.000 dengan 5."},{"i":1764,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 11 botol air mineral adalah Rp66.000. Dengan harga satuan yang sama, harga 15 botol air mineral adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu botol air mineral = Rp66.000 ÷ 11 = Rp6.000.\n2. Harga 15 botol air mineral = 15 × Rp6.000 = Rp90.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp66.000 × 15/11 = Rp90.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp48.400","Rp102.000","Rp84.000","Rp90.000","Rp96.000"],"s":[0,0,0,1,0],"w":["Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Ini harga 17 botol air mineral, bukan 15.","Kurang satu barang.","Benar. Langkahnya ada di pembahasan.","Kelebihan satu barang."],"h":"Cari harga satu botol air mineral dulu: bagi Rp66.000 dengan 11."},{"i":1765,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 21 orang dalam 18 hari. Jika dikerjakan 3 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 21 orang × 18 hari = 378 hari-orang.\n2. Dengan 3 orang: 378 ÷ 3 = 126 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 21 × 18 = 3 × x, jadi x = 378 ÷ 3 = 126.","o":["128","127","124","125","126"],"s":[0,0,0,0,1],"w":["Cek balik: 3 orang × 128 hari = 384 hari-orang, padahal beban kerjanya 378 hari-orang.","Cek balik: 3 orang × 127 hari = 381 hari-orang, padahal beban kerjanya 378 hari-orang.","Cek balik: 3 orang × 124 hari = 372 hari-orang, padahal beban kerjanya 378 hari-orang.","Cek balik: 3 orang × 125 hari = 375 hari-orang, padahal beban kerjanya 378 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1766,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 5 cm. Skala peta 1 : 2.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 5 × 2.000.000 = 10.000.000 cm.\n2. 1 km = 100.000 cm, jadi 10.000.000 ÷ 100.000 = 100 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.000.000 berarti 1 cm di peta = 20 km, jadi 5 × 20 = 100 km.","o":["105","10","1.000","100","95"],"s":[0,0,0,1,0],"w":["Cek balik: 105 km ÷ 20 km per cm = 5,25 cm di peta, padahal jaraknya 5 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Benar. Langkahnya ada di pembahasan.","Cek balik: 95 km ÷ 20 km per cm = 4,75 cm di peta, padahal jaraknya 5 cm."],"h":"Hapus lima angka nol dari skala: 1 : 2.000.000 berarti 1 cm di peta mewakili 20 km."},{"i":1767,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 11 orang dalam 33 hari. Jika dikerjakan 3 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 11 orang × 33 hari = 363 hari-orang.\n2. Dengan 3 orang: 363 ÷ 3 = 121 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 11 × 33 = 3 × x, jadi x = 363 ÷ 3 = 121.","o":["9","123","120","121","122"],"s":[0,0,0,1,0],"w":["Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 3 orang × 123 hari = 369 hari-orang, padahal beban kerjanya 363 hari-orang.","Cek balik: 3 orang × 120 hari = 360 hari-orang, padahal beban kerjanya 363 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 3 orang × 122 hari = 366 hari-orang, padahal beban kerjanya 363 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1768,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 5 orang dalam 32 hari. Jika dikerjakan 10 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 5 orang × 32 hari = 160 hari-orang.\n2. Dengan 10 orang: 160 ÷ 10 = 16 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 5 × 32 = 10 × x, jadi x = 160 ÷ 10 = 16.","o":["17","15","64","16","18"],"s":[0,0,0,1,0],"w":["Cek balik: 10 orang × 17 hari = 170 hari-orang, padahal beban kerjanya 160 hari-orang.","Cek balik: 10 orang × 15 hari = 150 hari-orang, padahal beban kerjanya 160 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Benar. Langkahnya ada di pembahasan.","Cek balik: 10 orang × 18 hari = 180 hari-orang, padahal beban kerjanya 160 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1769,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 11 roti adalah Rp115.500. Dengan harga satuan yang sama, harga 21 roti adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu roti = Rp115.500 ÷ 11 = Rp10.500.\n2. Harga 21 roti = 21 × Rp10.500 = Rp220.500.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp115.500 × 21/11 = Rp220.500. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp241.500","Rp220.500","Rp60.500","Rp210.000","Rp231.000"],"s":[0,1,0,0,0],"w":["Ini harga 23 roti, bukan 21.","Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Kurang satu barang.","Kelebihan satu barang."],"h":"Cari harga satu roti dulu: bagi Rp115.500 dengan 11."},{"i":1770,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 160 km dalam 4 jam. Dengan kecepatan yang sama, jarak 60 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 160 km ÷ 4 jam = 40 km/jam.\n2. Waktu = jarak ÷ kecepatan = 60 ÷ 40 = 1,5 jam.\nCara cepat: bandingkan jaraknya. 60 km adalah 0,375 kali 160 km, jadi waktunya 0,375 × 4 = 1,5 jam.","o":["1,5","0,5","1","2","2,5"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 0,5 jam × 40 km/jam = 20 km, padahal jaraknya 60 km.","Cek balik: 1 jam × 40 km/jam = 40 km, padahal jaraknya 60 km.","Cek balik: 2 jam × 40 km/jam = 80 km, padahal jaraknya 60 km.","Cek balik: 2,5 jam × 40 km/jam = 100 km, padahal jaraknya 60 km."],"h":"Cari kecepatannya dulu: 160 km dibagi 4 jam."},{"i":1771,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 21 orang dalam 19 hari. Jika dikerjakan 7 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 21 orang × 19 hari = 399 hari-orang.\n2. Dengan 7 orang: 399 ÷ 7 = 57 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 21 × 19 = 7 × x, jadi x = 399 ÷ 7 = 57.","o":["57","58","55","56","59"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 7 orang × 58 hari = 406 hari-orang, padahal beban kerjanya 399 hari-orang.","Cek balik: 7 orang × 55 hari = 385 hari-orang, padahal beban kerjanya 399 hari-orang.","Cek balik: 7 orang × 56 hari = 392 hari-orang, padahal beban kerjanya 399 hari-orang.","Cek balik: 7 orang × 59 hari = 413 hari-orang, padahal beban kerjanya 399 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1772,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 7,5 cm. Skala peta 1 : 500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 7,5 × 500.000 = 3.750.000 cm.\n2. 1 km = 100.000 cm, jadi 3.750.000 ÷ 100.000 = 37,5 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 500.000 berarti 1 cm di peta = 5 km, jadi 7,5 × 5 = 37,5 km.","o":["375","32,5","37,5","3,75","42,5"],"s":[0,0,1,0,0],"w":["Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 32,5 km ÷ 5 km per cm = 6,5 cm di peta, padahal jaraknya 7,5 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 42,5 km ÷ 5 km per cm = 8,5 cm di peta, padahal jaraknya 7,5 cm."],"h":"Hapus lima angka nol dari skala: 1 : 500.000 berarti 1 cm di peta mewakili 5 km."},{"i":1773,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 6 cm. Skala peta 1 : 3.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 6 × 3.000.000 = 18.000.000 cm.\n2. 1 km = 100.000 cm, jadi 18.000.000 ÷ 100.000 = 180 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 3.000.000 berarti 1 cm di peta = 30 km, jadi 6 × 30 = 180 km.","o":["1.800","175","18","180","185"],"s":[0,0,0,1,0],"w":["Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 175 km ÷ 30 km per cm = 35/6 cm di peta, padahal jaraknya 6 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Benar. Langkahnya ada di pembahasan.","Cek balik: 185 km ÷ 30 km per cm = 37/6 cm di peta, padahal jaraknya 6 cm."],"h":"Hapus lima angka nol dari skala: 1 : 3.000.000 berarti 1 cm di peta mewakili 30 km."},{"i":1774,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 320 km dalam 4 jam. Dengan kecepatan yang sama, jarak 200 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 320 km ÷ 4 jam = 80 km/jam.\n2. Waktu = jarak ÷ kecepatan = 200 ÷ 80 = 2,5 jam.\nCara cepat: bandingkan jaraknya. 200 km adalah 0,625 kali 320 km, jadi waktunya 0,625 × 4 = 2,5 jam.","o":["2,5","2","3","6,4","3,5"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 2 jam × 80 km/jam = 160 km, padahal jaraknya 200 km.","Cek balik: 3 jam × 80 km/jam = 240 km, padahal jaraknya 200 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 3,5 jam × 80 km/jam = 280 km, padahal jaraknya 200 km."],"h":"Cari kecepatannya dulu: 320 km dibagi 4 jam."},{"i":1776,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 16 orang dalam 33 hari. Jika dikerjakan 4 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 16 orang × 33 hari = 528 hari-orang.\n2. Dengan 4 orang: 528 ÷ 4 = 132 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 16 × 33 = 4 × x, jadi x = 528 ÷ 4 = 132.","o":["8,25","133","132","131","134"],"s":[0,0,1,0,0],"w":["Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 4 orang × 133 hari = 532 hari-orang, padahal beban kerjanya 528 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 4 orang × 131 hari = 524 hari-orang, padahal beban kerjanya 528 hari-orang.","Cek balik: 4 orang × 134 hari = 536 hari-orang, padahal beban kerjanya 528 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1777,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 9 buku tulis adalah Rp67.500. Dengan harga satuan yang sama, harga 6 buku tulis adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu buku tulis = Rp67.500 ÷ 9 = Rp7.500.\n2. Harga 6 buku tulis = 6 × Rp7.500 = Rp45.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp67.500 × 2/3 = Rp45.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp52.500","Rp45.000","Rp60.000","Rp37.500","Rp101.250"],"s":[0,1,0,0,0],"w":["Kelebihan satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 8 buku tulis, bukan 6.","Kurang satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai."],"h":"Cari harga satu buku tulis dulu: bagi Rp67.500 dengan 9."},{"i":1778,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 12 orang dalam 9 hari. Jika dikerjakan 18 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 12 orang × 9 hari = 108 hari-orang.\n2. Dengan 18 orang: 108 ÷ 18 = 6 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 12 × 9 = 18 × x, jadi x = 108 ÷ 18 = 6.","o":["13,5","5","7","8","6"],"s":[0,0,0,0,1],"w":["Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 18 orang × 5 hari = 90 hari-orang, padahal beban kerjanya 108 hari-orang.","Cek balik: 18 orang × 7 hari = 126 hari-orang, padahal beban kerjanya 108 hari-orang.","Cek balik: 18 orang × 8 hari = 144 hari-orang, padahal beban kerjanya 108 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1779,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 21 orang dalam 30 hari. Jika dikerjakan 15 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 21 orang × 30 hari = 630 hari-orang.\n2. Dengan 15 orang: 630 ÷ 15 = 42 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 21 × 30 = 15 × x, jadi x = 630 ÷ 15 = 42.","o":["43","41","40","44","42"],"s":[0,0,0,0,1],"w":["Cek balik: 15 orang × 43 hari = 645 hari-orang, padahal beban kerjanya 630 hari-orang.","Cek balik: 15 orang × 41 hari = 615 hari-orang, padahal beban kerjanya 630 hari-orang.","Cek balik: 15 orang × 40 hari = 600 hari-orang, padahal beban kerjanya 630 hari-orang.","Cek balik: 15 orang × 44 hari = 660 hari-orang, padahal beban kerjanya 630 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1780,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 10 roti adalah Rp50.000. Dengan harga satuan yang sama, harga 20 roti adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu roti = Rp50.000 ÷ 10 = Rp5.000.\n2. Harga 20 roti = 20 × Rp5.000 = Rp100.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp50.000 × 2 = Rp100.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp105.000","Rp100.000","Rp25.000","Rp95.000","Rp110.000"],"s":[0,1,0,0,0],"w":["Kelebihan satu barang.","Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Kurang satu barang.","Ini harga 22 roti, bukan 20."],"h":"Cari harga satu roti dulu: bagi Rp50.000 dengan 10."},{"i":1781,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 24 orang dalam 24 hari. Jika dikerjakan 18 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 24 orang × 24 hari = 576 hari-orang.\n2. Dengan 18 orang: 576 ÷ 18 = 32 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 24 × 24 = 18 × x, jadi x = 576 ÷ 18 = 32.","o":["34","18","32","33","31"],"s":[0,0,1,0,0],"w":["Cek balik: 18 orang × 34 hari = 612 hari-orang, padahal beban kerjanya 576 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Benar. Langkahnya ada di pembahasan.","Cek balik: 18 orang × 33 hari = 594 hari-orang, padahal beban kerjanya 576 hari-orang.","Cek balik: 18 orang × 31 hari = 558 hari-orang, padahal beban kerjanya 576 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1782,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 8 pulpen adalah Rp28.000. Dengan harga satuan yang sama, harga 26 pulpen adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu pulpen = Rp28.000 ÷ 8 = Rp3.500.\n2. Harga 26 pulpen = 26 × Rp3.500 = Rp91.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp28.000 × 3,25 = Rp91.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp87.500","Rp91.000","Rp98.000","Rp84.000","Rp94.500"],"s":[0,1,0,0,0],"w":["Kurang satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 28 pulpen, bukan 26.","Ini harga 24 pulpen, bukan 26.","Kelebihan satu barang."],"h":"Cari harga satu pulpen dulu: bagi Rp28.000 dengan 8."},{"i":1783,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 4 orang dalam 8 hari. Jika dikerjakan 8 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 4 orang × 8 hari = 32 hari-orang.\n2. Dengan 8 orang: 32 ÷ 8 = 4 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 4 × 8 = 8 × x, jadi x = 32 ÷ 8 = 4.","o":["5","16","4","3","6"],"s":[0,0,1,0,0],"w":["Cek balik: 8 orang × 5 hari = 40 hari-orang, padahal beban kerjanya 32 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Benar. Langkahnya ada di pembahasan.","Cek balik: 8 orang × 3 hari = 24 hari-orang, padahal beban kerjanya 32 hari-orang.","Cek balik: 8 orang × 6 hari = 48 hari-orang, padahal beban kerjanya 32 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1784,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 12 buku tulis adalah Rp42.000. Dengan harga satuan yang sama, harga 6 buku tulis adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu buku tulis = Rp42.000 ÷ 12 = Rp3.500.\n2. Harga 6 buku tulis = 6 × Rp3.500 = Rp21.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp42.000 × 0,5 = Rp21.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp84.000","Rp21.000","Rp17.500","Rp28.000","Rp24.500"],"s":[0,1,0,0,0],"w":["Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Benar. Langkahnya ada di pembahasan.","Kurang satu barang.","Ini harga 8 buku tulis, bukan 6.","Kelebihan satu barang."],"h":"Cari harga satu buku tulis dulu: bagi Rp42.000 dengan 12."},{"i":1787,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 10 orang dalam 9 hari. Jika dikerjakan 6 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 10 orang × 9 hari = 90 hari-orang.\n2. Dengan 6 orang: 90 ÷ 6 = 15 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 10 × 9 = 6 × x, jadi x = 90 ÷ 6 = 15.","o":["14","17","5,4","16","15"],"s":[0,0,0,0,1],"w":["Cek balik: 6 orang × 14 hari = 84 hari-orang, padahal beban kerjanya 90 hari-orang.","Cek balik: 6 orang × 17 hari = 102 hari-orang, padahal beban kerjanya 90 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 6 orang × 16 hari = 96 hari-orang, padahal beban kerjanya 90 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1788,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 7,5 cm. Skala peta 1 : 2.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 7,5 × 2.000.000 = 15.000.000 cm.\n2. 1 km = 100.000 cm, jadi 15.000.000 ÷ 100.000 = 150 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.000.000 berarti 1 cm di peta = 20 km, jadi 7,5 × 20 = 150 km.","o":["150","155","15","1.500","145"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 155 km ÷ 20 km per cm = 7,75 cm di peta, padahal jaraknya 7,5 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 145 km ÷ 20 km per cm = 7,25 cm di peta, padahal jaraknya 7,5 cm."],"h":"Hapus lima angka nol dari skala: 1 : 2.000.000 berarti 1 cm di peta mewakili 20 km."},{"i":1789,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 3 pulpen adalah Rp10.500. Dengan harga satuan yang sama, harga 25 pulpen adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu pulpen = Rp10.500 ÷ 3 = Rp3.500.\n2. Harga 25 pulpen = 25 × Rp3.500 = Rp87.500.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp10.500 × 25/3 = Rp87.500. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp1.260","Rp87.500","Rp84.000","Rp94.500","Rp91.000"],"s":[0,1,0,0,0],"w":["Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Benar. Langkahnya ada di pembahasan.","Kurang satu barang.","Ini harga 27 pulpen, bukan 25.","Kelebihan satu barang."],"h":"Cari harga satu pulpen dulu: bagi Rp10.500 dengan 3."},{"i":1790,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 5 roti adalah Rp50.000. Dengan harga satuan yang sama, harga 21 roti adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu roti = Rp50.000 ÷ 5 = Rp10.000.\n2. Harga 21 roti = 21 × Rp10.000 = Rp210.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp50.000 × 4,2 = Rp210.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp200.000","Rp210.000","Rp230.000","Rp220.000","Rp190.000"],"s":[0,1,0,0,0],"w":["Kurang satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 23 roti, bukan 21.","Kelebihan satu barang.","Ini harga 19 roti, bukan 21."],"h":"Cari harga satu roti dulu: bagi Rp50.000 dengan 5."},{"i":1791,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 250 km dalam 5 jam. Dengan kecepatan yang sama, jarak 200 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 250 km ÷ 5 jam = 50 km/jam.\n2. Waktu = jarak ÷ kecepatan = 200 ÷ 50 = 4 jam.\nCara cepat: bandingkan jaraknya. 200 km adalah 0,8 kali 250 km, jadi waktunya 0,8 × 5 = 4 jam.","o":["4","3,5","5","4,5","6,25"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 3,5 jam × 50 km/jam = 175 km, padahal jaraknya 200 km.","Cek balik: 5 jam × 50 km/jam = 250 km, padahal jaraknya 200 km.","Cek balik: 4,5 jam × 50 km/jam = 225 km, padahal jaraknya 200 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai."],"h":"Cari kecepatannya dulu: 250 km dibagi 5 jam."},{"i":1792,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 4 cm. Skala peta 1 : 2.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 4 × 2.000.000 = 8.000.000 cm.\n2. 1 km = 100.000 cm, jadi 8.000.000 ÷ 100.000 = 80 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.000.000 berarti 1 cm di peta = 20 km, jadi 4 × 20 = 80 km.","o":["85","80","800","8","75"],"s":[0,1,0,0,0],"w":["Cek balik: 85 km ÷ 20 km per cm = 4,25 cm di peta, padahal jaraknya 4 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 75 km ÷ 20 km per cm = 3,75 cm di peta, padahal jaraknya 4 cm."],"h":"Hapus lima angka nol dari skala: 1 : 2.000.000 berarti 1 cm di peta mewakili 20 km."},{"i":1793,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 8 kotak susu adalah Rp60.000. Dengan harga satuan yang sama, harga 26 kotak susu adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kotak susu = Rp60.000 ÷ 8 = Rp7.500.\n2. Harga 26 kotak susu = 26 × Rp7.500 = Rp195.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp60.000 × 3,25 = Rp195.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp195.000","Rp202.500","Rp187.500","Rp180.000","Rp210.000"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Kelebihan satu barang.","Kurang satu barang.","Ini harga 24 kotak susu, bukan 26.","Ini harga 28 kotak susu, bukan 26."],"h":"Cari harga satu kotak susu dulu: bagi Rp60.000 dengan 8."},{"i":1794,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 288 km dalam 4 jam. Dengan kecepatan yang sama, jarak 144 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 288 km ÷ 4 jam = 72 km/jam.\n2. Waktu = jarak ÷ kecepatan = 144 ÷ 72 = 2 jam.\nCara cepat: bandingkan jaraknya. 144 km adalah 0,5 kali 288 km, jadi waktunya 0,5 × 4 = 2 jam.","o":["2,5","1,5","2","3","8"],"s":[0,0,1,0,0],"w":["Cek balik: 2,5 jam × 72 km/jam = 180 km, padahal jaraknya 144 km.","Cek balik: 1,5 jam × 72 km/jam = 108 km, padahal jaraknya 144 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 3 jam × 72 km/jam = 216 km, padahal jaraknya 144 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai."],"h":"Cari kecepatannya dulu: 288 km dibagi 4 jam."},{"i":1795,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 250 km dalam 5 jam. Dengan kecepatan yang sama, jarak 150 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 250 km ÷ 5 jam = 50 km/jam.\n2. Waktu = jarak ÷ kecepatan = 150 ÷ 50 = 3 jam.\nCara cepat: bandingkan jaraknya. 150 km adalah 0,6 kali 250 km, jadi waktunya 0,6 × 5 = 3 jam.","o":["3","4","2","3,5","2,5"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 4 jam × 50 km/jam = 200 km, padahal jaraknya 150 km.","Cek balik: 2 jam × 50 km/jam = 100 km, padahal jaraknya 150 km.","Cek balik: 3,5 jam × 50 km/jam = 175 km, padahal jaraknya 150 km.","Cek balik: 2,5 jam × 50 km/jam = 125 km, padahal jaraknya 150 km."],"h":"Cari kecepatannya dulu: 250 km dibagi 5 jam."},{"i":1796,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 3 kotak susu adalah Rp25.500. Dengan harga satuan yang sama, harga 28 kotak susu adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kotak susu = Rp25.500 ÷ 3 = Rp8.500.\n2. Harga 28 kotak susu = 28 × Rp8.500 = Rp238.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp25.500 × 28/3 = Rp238.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp246.500","Rp221.000","Rp229.500","Rp238.000","Rp255.000"],"s":[0,0,0,1,0],"w":["Kelebihan satu barang.","Ini harga 26 kotak susu, bukan 28.","Kurang satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 30 kotak susu, bukan 28."],"h":"Cari harga satu kotak susu dulu: bagi Rp25.500 dengan 3."},{"i":1797,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 3,5 cm. Skala peta 1 : 1.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 3,5 × 1.000.000 = 3.500.000 cm.\n2. 1 km = 100.000 cm, jadi 3.500.000 ÷ 100.000 = 35 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.000.000 berarti 1 cm di peta = 10 km, jadi 3,5 × 10 = 35 km.","o":["30","35","3,5","40","350"],"s":[0,1,0,0,0],"w":["Cek balik: 30 km ÷ 10 km per cm = 3 cm di peta, padahal jaraknya 3,5 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 40 km ÷ 10 km per cm = 4 cm di peta, padahal jaraknya 3,5 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000."],"h":"Hapus lima angka nol dari skala: 1 : 1.000.000 berarti 1 cm di peta mewakili 10 km."},{"i":1798,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 3 cm. Skala peta 1 : 2.500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 3 × 2.500.000 = 7.500.000 cm.\n2. 1 km = 100.000 cm, jadi 7.500.000 ÷ 100.000 = 75 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.500.000 berarti 1 cm di peta = 25 km, jadi 3 × 25 = 75 km.","o":["7,5","80","750","75","70"],"s":[0,0,0,1,0],"w":["Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 80 km ÷ 25 km per cm = 3,2 cm di peta, padahal jaraknya 3 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Benar. Langkahnya ada di pembahasan.","Cek balik: 70 km ÷ 25 km per cm = 2,8 cm di peta, padahal jaraknya 3 cm."],"h":"Hapus lima angka nol dari skala: 1 : 2.500.000 berarti 1 cm di peta mewakili 25 km."},{"i":1799,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 4,5 cm. Skala peta 1 : 1.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 4,5 × 1.000.000 = 4.500.000 cm.\n2. 1 km = 100.000 cm, jadi 4.500.000 ÷ 100.000 = 45 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.000.000 berarti 1 cm di peta = 10 km, jadi 4,5 × 10 = 45 km.","o":["4,5","40","45","450","50"],"s":[0,0,1,0,0],"w":["Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 40 km ÷ 10 km per cm = 4 cm di peta, padahal jaraknya 4,5 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 50 km ÷ 10 km per cm = 5 cm di peta, padahal jaraknya 4,5 cm."],"h":"Hapus lima angka nol dari skala: 1 : 1.000.000 berarti 1 cm di peta mewakili 10 km."},{"i":1800,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 28 orang dalam 32 hari. Jika dikerjakan 8 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 28 orang × 32 hari = 896 hari-orang.\n2. Dengan 8 orang: 896 ÷ 8 = 112 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 28 × 32 = 8 × x, jadi x = 896 ÷ 8 = 112.","o":["112","111","110","113","114"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 8 orang × 111 hari = 888 hari-orang, padahal beban kerjanya 896 hari-orang.","Cek balik: 8 orang × 110 hari = 880 hari-orang, padahal beban kerjanya 896 hari-orang.","Cek balik: 8 orang × 113 hari = 904 hari-orang, padahal beban kerjanya 896 hari-orang.","Cek balik: 8 orang × 114 hari = 912 hari-orang, padahal beban kerjanya 896 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1801,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 18 orang dalam 20 hari. Jika dikerjakan 8 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 18 orang × 20 hari = 360 hari-orang.\n2. Dengan 8 orang: 360 ÷ 8 = 45 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 18 × 20 = 8 × x, jadi x = 360 ÷ 8 = 45.","o":["46","45","47","43","44"],"s":[0,1,0,0,0],"w":["Cek balik: 8 orang × 46 hari = 368 hari-orang, padahal beban kerjanya 360 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 8 orang × 47 hari = 376 hari-orang, padahal beban kerjanya 360 hari-orang.","Cek balik: 8 orang × 43 hari = 344 hari-orang, padahal beban kerjanya 360 hari-orang.","Cek balik: 8 orang × 44 hari = 352 hari-orang, padahal beban kerjanya 360 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1802,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 270 km dalam 3 jam. Dengan kecepatan yang sama, jarak 450 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 270 km ÷ 3 jam = 90 km/jam.\n2. Waktu = jarak ÷ kecepatan = 450 ÷ 90 = 5 jam.\nCara cepat: bandingkan jaraknya. 450 km adalah 5/3 kali 270 km, jadi waktunya 5/3 × 3 = 5 jam.","o":["5","6","4,5","5,5","1,8"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 6 jam × 90 km/jam = 540 km, padahal jaraknya 450 km.","Cek balik: 4,5 jam × 90 km/jam = 405 km, padahal jaraknya 450 km.","Cek balik: 5,5 jam × 90 km/jam = 495 km, padahal jaraknya 450 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai."],"h":"Cari kecepatannya dulu: 270 km dibagi 3 jam."},{"i":1803,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 18 orang dalam 11 hari. Jika dikerjakan 33 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 18 orang × 11 hari = 198 hari-orang.\n2. Dengan 33 orang: 198 ÷ 33 = 6 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 18 × 11 = 33 × x, jadi x = 198 ÷ 33 = 6.","o":["5","6","8","7","4"],"s":[0,1,0,0,0],"w":["Cek balik: 33 orang × 5 hari = 165 hari-orang, padahal beban kerjanya 198 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 33 orang × 8 hari = 264 hari-orang, padahal beban kerjanya 198 hari-orang.","Cek balik: 33 orang × 7 hari = 231 hari-orang, padahal beban kerjanya 198 hari-orang.","Cek balik: 33 orang × 4 hari = 132 hari-orang, padahal beban kerjanya 198 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1804,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 300 km dalam 4 jam. Dengan kecepatan yang sama, jarak 450 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 300 km ÷ 4 jam = 75 km/jam.\n2. Waktu = jarak ÷ kecepatan = 450 ÷ 75 = 6 jam.\nCara cepat: bandingkan jaraknya. 450 km adalah 1,5 kali 300 km, jadi waktunya 1,5 × 4 = 6 jam.","o":["7","6","5,5","5","6,5"],"s":[0,1,0,0,0],"w":["Cek balik: 7 jam × 75 km/jam = 525 km, padahal jaraknya 450 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 5,5 jam × 75 km/jam = 412,5 km, padahal jaraknya 450 km.","Cek balik: 5 jam × 75 km/jam = 375 km, padahal jaraknya 450 km.","Cek balik: 6,5 jam × 75 km/jam = 487,5 km, padahal jaraknya 450 km."],"h":"Cari kecepatannya dulu: 300 km dibagi 4 jam."},{"i":1805,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 2,5 cm. Skala peta 1 : 500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 2,5 × 500.000 = 1.250.000 cm.\n2. 1 km = 100.000 cm, jadi 1.250.000 ÷ 100.000 = 12,5 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 500.000 berarti 1 cm di peta = 5 km, jadi 2,5 × 5 = 12,5 km.","o":["17,5","1,25","7,5","12,5","125"],"s":[0,0,0,1,0],"w":["Cek balik: 17,5 km ÷ 5 km per cm = 3,5 cm di peta, padahal jaraknya 2,5 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 7,5 km ÷ 5 km per cm = 1,5 cm di peta, padahal jaraknya 2,5 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000."],"h":"Hapus lima angka nol dari skala: 1 : 500.000 berarti 1 cm di peta mewakili 5 km."},{"i":1806,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 2,5 cm. Skala peta 1 : 1.500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 2,5 × 1.500.000 = 3.750.000 cm.\n2. 1 km = 100.000 cm, jadi 3.750.000 ÷ 100.000 = 37,5 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.500.000 berarti 1 cm di peta = 15 km, jadi 2,5 × 15 = 37,5 km.","o":["3,75","32,5","37,5","42,5","375"],"s":[0,0,1,0,0],"w":["Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 32,5 km ÷ 15 km per cm = 13/6 cm di peta, padahal jaraknya 2,5 cm.","Benar. Langkahnya ada di pembahasan.","Cek balik: 42,5 km ÷ 15 km per cm = 17/6 cm di peta, padahal jaraknya 2,5 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000."],"h":"Hapus lima angka nol dari skala: 1 : 1.500.000 berarti 1 cm di peta mewakili 15 km."},{"i":1807,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 160 km dalam 2 jam. Dengan kecepatan yang sama, jarak 120 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 160 km ÷ 2 jam = 80 km/jam.\n2. Waktu = jarak ÷ kecepatan = 120 ÷ 80 = 1,5 jam.\nCara cepat: bandingkan jaraknya. 120 km adalah 0,75 kali 160 km, jadi waktunya 0,75 × 2 = 1,5 jam.","o":["1,5","2","0,5","2,5","1"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 2 jam × 80 km/jam = 160 km, padahal jaraknya 120 km.","Cek balik: 0,5 jam × 80 km/jam = 40 km, padahal jaraknya 120 km.","Cek balik: 2,5 jam × 80 km/jam = 200 km, padahal jaraknya 120 km.","Cek balik: 1 jam × 80 km/jam = 80 km, padahal jaraknya 120 km."],"h":"Cari kecepatannya dulu: 160 km dibagi 2 jam."},{"i":1809,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 24 orang dalam 36 hari. Jika dikerjakan 27 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 24 orang × 36 hari = 864 hari-orang.\n2. Dengan 27 orang: 864 ÷ 27 = 32 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 24 × 36 = 27 × x, jadi x = 864 ÷ 27 = 32.","o":["32","33","31","40,5","34"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 27 orang × 33 hari = 891 hari-orang, padahal beban kerjanya 864 hari-orang.","Cek balik: 27 orang × 31 hari = 837 hari-orang, padahal beban kerjanya 864 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 27 orang × 34 hari = 918 hari-orang, padahal beban kerjanya 864 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1810,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 5 orang dalam 36 hari. Jika dikerjakan 20 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 5 orang × 36 hari = 180 hari-orang.\n2. Dengan 20 orang: 180 ÷ 20 = 9 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 5 × 36 = 20 × x, jadi x = 180 ÷ 20 = 9.","o":["11","8","144","9","10"],"s":[0,0,0,1,0],"w":["Cek balik: 20 orang × 11 hari = 220 hari-orang, padahal beban kerjanya 180 hari-orang.","Cek balik: 20 orang × 8 hari = 160 hari-orang, padahal beban kerjanya 180 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Benar. Langkahnya ada di pembahasan.","Cek balik: 20 orang × 10 hari = 200 hari-orang, padahal beban kerjanya 180 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1811,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 7 orang dalam 24 hari. Jika dikerjakan 28 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 7 orang × 24 hari = 168 hari-orang.\n2. Dengan 28 orang: 168 ÷ 28 = 6 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 7 × 24 = 28 × x, jadi x = 168 ÷ 28 = 6.","o":["6","96","5","8","7"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 28 orang × 5 hari = 140 hari-orang, padahal beban kerjanya 168 hari-orang.","Cek balik: 28 orang × 8 hari = 224 hari-orang, padahal beban kerjanya 168 hari-orang.","Cek balik: 28 orang × 7 hari = 196 hari-orang, padahal beban kerjanya 168 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1812,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 11 botol air mineral adalah Rp77.000. Dengan harga satuan yang sama, harga 20 botol air mineral adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu botol air mineral = Rp77.000 ÷ 11 = Rp7.000.\n2. Harga 20 botol air mineral = 20 × Rp7.000 = Rp140.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp77.000 × 20/11 = Rp140.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp42.350","Rp133.000","Rp154.000","Rp147.000","Rp140.000"],"s":[0,0,0,0,1],"w":["Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Kurang satu barang.","Ini harga 22 botol air mineral, bukan 20.","Kelebihan satu barang.","Benar. Langkahnya ada di pembahasan."],"h":"Cari harga satu botol air mineral dulu: bagi Rp77.000 dengan 11."},{"i":1813,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 7 kotak susu adalah Rp35.000. Dengan harga satuan yang sama, harga 4 kotak susu adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kotak susu = Rp35.000 ÷ 7 = Rp5.000.\n2. Harga 4 kotak susu = 4 × Rp5.000 = Rp20.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp35.000 × 4/7 = Rp20.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp20.000","Rp30.000","Rp15.000","Rp25.000","Rp61.250"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Ini harga 6 kotak susu, bukan 4.","Kurang satu barang.","Kelebihan satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai."],"h":"Cari harga satu kotak susu dulu: bagi Rp35.000 dengan 7."},{"i":1814,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 20 orang dalam 18 hari. Jika dikerjakan 4 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 20 orang × 18 hari = 360 hari-orang.\n2. Dengan 4 orang: 360 ÷ 4 = 90 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 20 × 18 = 4 × x, jadi x = 360 ÷ 4 = 90.","o":["92","89","3,6","90","91"],"s":[0,0,0,1,0],"w":["Cek balik: 4 orang × 92 hari = 368 hari-orang, padahal beban kerjanya 360 hari-orang.","Cek balik: 4 orang × 89 hari = 356 hari-orang, padahal beban kerjanya 360 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Benar. Langkahnya ada di pembahasan.","Cek balik: 4 orang × 91 hari = 364 hari-orang, padahal beban kerjanya 360 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1815,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 3 botol air mineral adalah Rp15.000. Dengan harga satuan yang sama, harga 14 botol air mineral adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu botol air mineral = Rp15.000 ÷ 3 = Rp5.000.\n2. Harga 14 botol air mineral = 14 × Rp5.000 = Rp70.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp15.000 × 14/3 = Rp70.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp60.000","Rp75.000","Rp65.000","Rp70.000","Rp80.000"],"s":[0,0,0,1,0],"w":["Ini harga 12 botol air mineral, bukan 14.","Kelebihan satu barang.","Kurang satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 16 botol air mineral, bukan 14."],"h":"Cari harga satu botol air mineral dulu: bagi Rp15.000 dengan 3."},{"i":1816,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 10 kaus adalah Rp630.000. Dengan harga satuan yang sama, harga 30 kaus adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kaus = Rp630.000 ÷ 10 = Rp63.000.\n2. Harga 30 kaus = 30 × Rp63.000 = Rp1.890.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp630.000 × 3 = Rp1.890.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp1.827.000","Rp2.016.000","Rp210.000","Rp1.890.000","Rp1.953.000"],"s":[0,0,0,1,0],"w":["Kurang satu barang.","Ini harga 32 kaus, bukan 30.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Benar. Langkahnya ada di pembahasan.","Kelebihan satu barang."],"h":"Cari harga satu kaus dulu: bagi Rp630.000 dengan 10."},{"i":1817,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 4 cm. Skala peta 1 : 1.500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 4 × 1.500.000 = 6.000.000 cm.\n2. 1 km = 100.000 cm, jadi 6.000.000 ÷ 100.000 = 60 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.500.000 berarti 1 cm di peta = 15 km, jadi 4 × 15 = 60 km.","o":["60","600","6","65","55"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 65 km ÷ 15 km per cm = 13/3 cm di peta, padahal jaraknya 4 cm.","Cek balik: 55 km ÷ 15 km per cm = 11/3 cm di peta, padahal jaraknya 4 cm."],"h":"Hapus lima angka nol dari skala: 1 : 1.500.000 berarti 1 cm di peta mewakili 15 km."},{"i":1818,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 14 orang dalam 22 hari. Jika dikerjakan 11 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 14 orang × 22 hari = 308 hari-orang.\n2. Dengan 11 orang: 308 ÷ 11 = 28 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 14 × 22 = 11 × x, jadi x = 308 ÷ 11 = 28.","o":["30","27","26","28","29"],"s":[0,0,0,1,0],"w":["Cek balik: 11 orang × 30 hari = 330 hari-orang, padahal beban kerjanya 308 hari-orang.","Cek balik: 11 orang × 27 hari = 297 hari-orang, padahal beban kerjanya 308 hari-orang.","Cek balik: 11 orang × 26 hari = 286 hari-orang, padahal beban kerjanya 308 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 11 orang × 29 hari = 319 hari-orang, padahal beban kerjanya 308 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1819,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 10 orang dalam 11 hari. Jika dikerjakan 11 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 10 orang × 11 hari = 110 hari-orang.\n2. Dengan 11 orang: 110 ÷ 11 = 10 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 10 × 11 = 11 × x, jadi x = 110 ÷ 11 = 10.","o":["12","10","11","12,1","9"],"s":[0,1,0,0,0],"w":["Cek balik: 11 orang × 12 hari = 132 hari-orang, padahal beban kerjanya 110 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 11 orang × 11 hari = 121 hari-orang, padahal beban kerjanya 110 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 11 orang × 9 hari = 99 hari-orang, padahal beban kerjanya 110 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1820,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 200 km dalam 5 jam. Dengan kecepatan yang sama, jarak 160 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 200 km ÷ 5 jam = 40 km/jam.\n2. Waktu = jarak ÷ kecepatan = 160 ÷ 40 = 4 jam.\nCara cepat: bandingkan jaraknya. 160 km adalah 0,8 kali 200 km, jadi waktunya 0,8 × 5 = 4 jam.","o":["4","3,5","6,25","5","4,5"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 3,5 jam × 40 km/jam = 140 km, padahal jaraknya 160 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 5 jam × 40 km/jam = 200 km, padahal jaraknya 160 km.","Cek balik: 4,5 jam × 40 km/jam = 180 km, padahal jaraknya 160 km."],"h":"Cari kecepatannya dulu: 200 km dibagi 5 jam."},{"i":1821,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 8 kotak susu adalah Rp64.000. Dengan harga satuan yang sama, harga 24 kotak susu adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kotak susu = Rp64.000 ÷ 8 = Rp8.000.\n2. Harga 24 kotak susu = 24 × Rp8.000 = Rp192.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp64.000 × 3 = Rp192.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp176.000","Rp200.000","Rp208.000","Rp192.000","Rp184.000"],"s":[0,0,0,1,0],"w":["Ini harga 22 kotak susu, bukan 24.","Kelebihan satu barang.","Ini harga 26 kotak susu, bukan 24.","Benar. Langkahnya ada di pembahasan.","Kurang satu barang."],"h":"Cari harga satu kotak susu dulu: bagi Rp64.000 dengan 8."},{"i":1822,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 5 buku tulis adalah Rp30.000. Dengan harga satuan yang sama, harga 3 buku tulis adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu buku tulis = Rp30.000 ÷ 5 = Rp6.000.\n2. Harga 3 buku tulis = 3 × Rp6.000 = Rp18.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp30.000 × 0,6 = Rp18.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp24.000","Rp18.000","Rp50.000","Rp30.000","Rp12.000"],"s":[0,1,0,0,0],"w":["Kelebihan satu barang.","Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Ini harga 5 buku tulis, bukan 3.","Kurang satu barang."],"h":"Cari harga satu buku tulis dulu: bagi Rp30.000 dengan 5."},{"i":1823,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 7,5 cm. Skala peta 1 : 1.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 7,5 × 1.000.000 = 7.500.000 cm.\n2. 1 km = 100.000 cm, jadi 7.500.000 ÷ 100.000 = 75 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.000.000 berarti 1 cm di peta = 10 km, jadi 7,5 × 10 = 75 km.","o":["750","80","70","75","7,5"],"s":[0,0,0,1,0],"w":["Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 80 km ÷ 10 km per cm = 8 cm di peta, padahal jaraknya 7,5 cm.","Cek balik: 70 km ÷ 10 km per cm = 7 cm di peta, padahal jaraknya 7,5 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm."],"h":"Hapus lima angka nol dari skala: 1 : 1.000.000 berarti 1 cm di peta mewakili 10 km."},{"i":1825,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 24 orang dalam 20 hari. Jika dikerjakan 6 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 24 orang × 20 hari = 480 hari-orang.\n2. Dengan 6 orang: 480 ÷ 6 = 80 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 24 × 20 = 6 × x, jadi x = 480 ÷ 6 = 80.","o":["82","81","80","79","5"],"s":[0,0,1,0,0],"w":["Cek balik: 6 orang × 82 hari = 492 hari-orang, padahal beban kerjanya 480 hari-orang.","Cek balik: 6 orang × 81 hari = 486 hari-orang, padahal beban kerjanya 480 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 6 orang × 79 hari = 474 hari-orang, padahal beban kerjanya 480 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1827,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 5 cm. Skala peta 1 : 2.500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 5 × 2.500.000 = 12.500.000 cm.\n2. 1 km = 100.000 cm, jadi 12.500.000 ÷ 100.000 = 125 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.500.000 berarti 1 cm di peta = 25 km, jadi 5 × 25 = 125 km.","o":["12,5","125","1.250","130","120"],"s":[0,1,0,0,0],"w":["Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 130 km ÷ 25 km per cm = 5,2 cm di peta, padahal jaraknya 5 cm.","Cek balik: 120 km ÷ 25 km per cm = 4,8 cm di peta, padahal jaraknya 5 cm."],"h":"Hapus lima angka nol dari skala: 1 : 2.500.000 berarti 1 cm di peta mewakili 25 km."},{"i":1828,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 22 orang dalam 39 hari. Jika dikerjakan 13 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 22 orang × 39 hari = 858 hari-orang.\n2. Dengan 13 orang: 858 ÷ 13 = 66 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 22 × 39 = 13 × x, jadi x = 858 ÷ 13 = 66.","o":["64","65","66","67","68"],"s":[0,0,1,0,0],"w":["Cek balik: 13 orang × 64 hari = 832 hari-orang, padahal beban kerjanya 858 hari-orang.","Cek balik: 13 orang × 65 hari = 845 hari-orang, padahal beban kerjanya 858 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 13 orang × 67 hari = 871 hari-orang, padahal beban kerjanya 858 hari-orang.","Cek balik: 13 orang × 68 hari = 884 hari-orang, padahal beban kerjanya 858 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1829,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 3,5 cm. Skala peta 1 : 2.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 3,5 × 2.000.000 = 7.000.000 cm.\n2. 1 km = 100.000 cm, jadi 7.000.000 ÷ 100.000 = 70 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.000.000 berarti 1 cm di peta = 20 km, jadi 3,5 × 20 = 70 km.","o":["700","65","75","7","70"],"s":[0,0,0,0,1],"w":["Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 65 km ÷ 20 km per cm = 3,25 cm di peta, padahal jaraknya 3,5 cm.","Cek balik: 75 km ÷ 20 km per cm = 3,75 cm di peta, padahal jaraknya 3,5 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Benar. Langkahnya ada di pembahasan."],"h":"Hapus lima angka nol dari skala: 1 : 2.000.000 berarti 1 cm di peta mewakili 20 km."},{"i":1830,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 24 orang dalam 11 hari. Jika dikerjakan 12 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 24 orang × 11 hari = 264 hari-orang.\n2. Dengan 12 orang: 264 ÷ 12 = 22 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 24 × 11 = 12 × x, jadi x = 264 ÷ 12 = 22.","o":["23","5,5","22","24","21"],"s":[0,0,1,0,0],"w":["Cek balik: 12 orang × 23 hari = 276 hari-orang, padahal beban kerjanya 264 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Benar. Langkahnya ada di pembahasan.","Cek balik: 12 orang × 24 hari = 288 hari-orang, padahal beban kerjanya 264 hari-orang.","Cek balik: 12 orang × 21 hari = 252 hari-orang, padahal beban kerjanya 264 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1831,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 225 km dalam 5 jam. Dengan kecepatan yang sama, jarak 90 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 225 km ÷ 5 jam = 45 km/jam.\n2. Waktu = jarak ÷ kecepatan = 90 ÷ 45 = 2 jam.\nCara cepat: bandingkan jaraknya. 90 km adalah 0,4 kali 225 km, jadi waktunya 0,4 × 5 = 2 jam.","o":["2","1,5","2,5","3","12,5"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 1,5 jam × 45 km/jam = 67,5 km, padahal jaraknya 90 km.","Cek balik: 2,5 jam × 45 km/jam = 112,5 km, padahal jaraknya 90 km.","Cek balik: 3 jam × 45 km/jam = 135 km, padahal jaraknya 90 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai."],"h":"Cari kecepatannya dulu: 225 km dibagi 5 jam."},{"i":1832,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 21 orang dalam 36 hari. Jika dikerjakan 9 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 21 orang × 36 hari = 756 hari-orang.\n2. Dengan 9 orang: 756 ÷ 9 = 84 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 21 × 36 = 9 × x, jadi x = 756 ÷ 9 = 84.","o":["84","82","85","83","86"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 9 orang × 82 hari = 738 hari-orang, padahal beban kerjanya 756 hari-orang.","Cek balik: 9 orang × 85 hari = 765 hari-orang, padahal beban kerjanya 756 hari-orang.","Cek balik: 9 orang × 83 hari = 747 hari-orang, padahal beban kerjanya 756 hari-orang.","Cek balik: 9 orang × 86 hari = 774 hari-orang, padahal beban kerjanya 756 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1833,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 12 orang dalam 28 hari. Jika dikerjakan 7 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 12 orang × 28 hari = 336 hari-orang.\n2. Dengan 7 orang: 336 ÷ 7 = 48 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 12 × 28 = 7 × x, jadi x = 336 ÷ 7 = 48.","o":["48","50","46","47","49"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 7 orang × 50 hari = 350 hari-orang, padahal beban kerjanya 336 hari-orang.","Cek balik: 7 orang × 46 hari = 322 hari-orang, padahal beban kerjanya 336 hari-orang.","Cek balik: 7 orang × 47 hari = 329 hari-orang, padahal beban kerjanya 336 hari-orang.","Cek balik: 7 orang × 49 hari = 343 hari-orang, padahal beban kerjanya 336 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1834,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 22 orang dalam 15 hari. Jika dikerjakan 6 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 22 orang × 15 hari = 330 hari-orang.\n2. Dengan 6 orang: 330 ÷ 6 = 55 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 22 × 15 = 6 × x, jadi x = 330 ÷ 6 = 55.","o":["54","56","57","53","55"],"s":[0,0,0,0,1],"w":["Cek balik: 6 orang × 54 hari = 324 hari-orang, padahal beban kerjanya 330 hari-orang.","Cek balik: 6 orang × 56 hari = 336 hari-orang, padahal beban kerjanya 330 hari-orang.","Cek balik: 6 orang × 57 hari = 342 hari-orang, padahal beban kerjanya 330 hari-orang.","Cek balik: 6 orang × 53 hari = 318 hari-orang, padahal beban kerjanya 330 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1836,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 200 km dalam 4 jam. Dengan kecepatan yang sama, jarak 250 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 200 km ÷ 4 jam = 50 km/jam.\n2. Waktu = jarak ÷ kecepatan = 250 ÷ 50 = 5 jam.\nCara cepat: bandingkan jaraknya. 250 km adalah 1,25 kali 200 km, jadi waktunya 1,25 × 4 = 5 jam.","o":["3,2","5,5","6","4,5","5"],"s":[0,0,0,0,1],"w":["Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 5,5 jam × 50 km/jam = 275 km, padahal jaraknya 250 km.","Cek balik: 6 jam × 50 km/jam = 300 km, padahal jaraknya 250 km.","Cek balik: 4,5 jam × 50 km/jam = 225 km, padahal jaraknya 250 km.","Benar. Langkahnya ada di pembahasan."],"h":"Cari kecepatannya dulu: 200 km dibagi 4 jam."},{"i":1837,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 21 orang dalam 21 hari. Jika dikerjakan 7 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 21 orang × 21 hari = 441 hari-orang.\n2. Dengan 7 orang: 441 ÷ 7 = 63 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 21 × 21 = 7 × x, jadi x = 441 ÷ 7 = 63.","o":["64","63","65","7","62"],"s":[0,1,0,0,0],"w":["Cek balik: 7 orang × 64 hari = 448 hari-orang, padahal beban kerjanya 441 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 7 orang × 65 hari = 455 hari-orang, padahal beban kerjanya 441 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 7 orang × 62 hari = 434 hari-orang, padahal beban kerjanya 441 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1840,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 240 km dalam 4 jam. Dengan kecepatan yang sama, jarak 300 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 240 km ÷ 4 jam = 60 km/jam.\n2. Waktu = jarak ÷ kecepatan = 300 ÷ 60 = 5 jam.\nCara cepat: bandingkan jaraknya. 300 km adalah 1,25 kali 240 km, jadi waktunya 1,25 × 4 = 5 jam.","o":["4,5","3,2","6","5,5","5"],"s":[0,0,0,0,1],"w":["Cek balik: 4,5 jam × 60 km/jam = 270 km, padahal jaraknya 300 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 6 jam × 60 km/jam = 360 km, padahal jaraknya 300 km.","Cek balik: 5,5 jam × 60 km/jam = 330 km, padahal jaraknya 300 km.","Benar. Langkahnya ada di pembahasan."],"h":"Cari kecepatannya dulu: 240 km dibagi 4 jam."},{"i":1841,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 6 botol air mineral adalah Rp42.000. Dengan harga satuan yang sama, harga 3 botol air mineral adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu botol air mineral = Rp42.000 ÷ 6 = Rp7.000.\n2. Harga 3 botol air mineral = 3 × Rp7.000 = Rp21.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp42.000 × 0,5 = Rp21.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp21.000","Rp14.000","Rp84.000","Rp28.000","Rp35.000"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Kurang satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Kelebihan satu barang.","Ini harga 5 botol air mineral, bukan 3."],"h":"Cari harga satu botol air mineral dulu: bagi Rp42.000 dengan 6."},{"i":1842,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 28 orang dalam 9 hari. Jika dikerjakan 14 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 28 orang × 9 hari = 252 hari-orang.\n2. Dengan 14 orang: 252 ÷ 14 = 18 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 28 × 9 = 14 × x, jadi x = 252 ÷ 14 = 18.","o":["18","20","4,5","19","17"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 14 orang × 20 hari = 280 hari-orang, padahal beban kerjanya 252 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 14 orang × 19 hari = 266 hari-orang, padahal beban kerjanya 252 hari-orang.","Cek balik: 14 orang × 17 hari = 238 hari-orang, padahal beban kerjanya 252 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1843,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 18 orang dalam 28 hari. Jika dikerjakan 12 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 18 orang × 28 hari = 504 hari-orang.\n2. Dengan 12 orang: 504 ÷ 12 = 42 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 18 × 28 = 12 × x, jadi x = 504 ÷ 12 = 42.","o":["43","44","40","41","42"],"s":[0,0,0,0,1],"w":["Cek balik: 12 orang × 43 hari = 516 hari-orang, padahal beban kerjanya 504 hari-orang.","Cek balik: 12 orang × 44 hari = 528 hari-orang, padahal beban kerjanya 504 hari-orang.","Cek balik: 12 orang × 40 hari = 480 hari-orang, padahal beban kerjanya 504 hari-orang.","Cek balik: 12 orang × 41 hari = 492 hari-orang, padahal beban kerjanya 504 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1844,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 14 orang dalam 30 hari. Jika dikerjakan 15 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 14 orang × 30 hari = 420 hari-orang.\n2. Dengan 15 orang: 420 ÷ 15 = 28 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 14 × 30 = 15 × x, jadi x = 420 ÷ 15 = 28.","o":["27","30","29","26","28"],"s":[0,0,0,0,1],"w":["Cek balik: 15 orang × 27 hari = 405 hari-orang, padahal beban kerjanya 420 hari-orang.","Cek balik: 15 orang × 30 hari = 450 hari-orang, padahal beban kerjanya 420 hari-orang.","Cek balik: 15 orang × 29 hari = 435 hari-orang, padahal beban kerjanya 420 hari-orang.","Cek balik: 15 orang × 26 hari = 390 hari-orang, padahal beban kerjanya 420 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1845,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 10 roti adalah Rp70.000. Dengan harga satuan yang sama, harga 6 roti adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu roti = Rp70.000 ÷ 10 = Rp7.000.\n2. Harga 6 roti = 6 × Rp7.000 = Rp42.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp70.000 × 0,6 = Rp42.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp56.000","Rp28.000","Rp42.000","Rp49.000","Rp35.000"],"s":[0,0,1,0,0],"w":["Ini harga 8 roti, bukan 6.","Ini harga 4 roti, bukan 6.","Benar. Langkahnya ada di pembahasan.","Kelebihan satu barang.","Kurang satu barang."],"h":"Cari harga satu roti dulu: bagi Rp70.000 dengan 10."},{"i":1846,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 360 km dalam 4 jam. Dengan kecepatan yang sama, jarak 270 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 360 km ÷ 4 jam = 90 km/jam.\n2. Waktu = jarak ÷ kecepatan = 270 ÷ 90 = 3 jam.\nCara cepat: bandingkan jaraknya. 270 km adalah 0,75 kali 360 km, jadi waktunya 0,75 × 4 = 3 jam.","o":["3,5","2","4","3","2,5"],"s":[0,0,0,1,0],"w":["Cek balik: 3,5 jam × 90 km/jam = 315 km, padahal jaraknya 270 km.","Cek balik: 2 jam × 90 km/jam = 180 km, padahal jaraknya 270 km.","Cek balik: 4 jam × 90 km/jam = 360 km, padahal jaraknya 270 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 2,5 jam × 90 km/jam = 225 km, padahal jaraknya 270 km."],"h":"Cari kecepatannya dulu: 360 km dibagi 4 jam."},{"i":1847,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 2 botol air mineral adalah Rp10.000. Dengan harga satuan yang sama, harga 23 botol air mineral adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu botol air mineral = Rp10.000 ÷ 2 = Rp5.000.\n2. Harga 23 botol air mineral = 23 × Rp5.000 = Rp115.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp10.000 × 11,5 = Rp115.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp115.000","Rp110.000","Rp125.000","Rp120.000","Rp105.000"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Kurang satu barang.","Ini harga 25 botol air mineral, bukan 23.","Kelebihan satu barang.","Ini harga 21 botol air mineral, bukan 23."],"h":"Cari harga satu botol air mineral dulu: bagi Rp10.000 dengan 2."},{"i":1848,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 22 orang dalam 40 hari. Jika dikerjakan 11 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 22 orang × 40 hari = 880 hari-orang.\n2. Dengan 11 orang: 880 ÷ 11 = 80 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 22 × 40 = 11 × x, jadi x = 880 ÷ 11 = 80.","o":["80","20","79","82","81"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 11 orang × 79 hari = 869 hari-orang, padahal beban kerjanya 880 hari-orang.","Cek balik: 11 orang × 82 hari = 902 hari-orang, padahal beban kerjanya 880 hari-orang.","Cek balik: 11 orang × 81 hari = 891 hari-orang, padahal beban kerjanya 880 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1850,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 3 roti adalah Rp33.000. Dengan harga satuan yang sama, harga 15 roti adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu roti = Rp33.000 ÷ 3 = Rp11.000.\n2. Harga 15 roti = 15 × Rp11.000 = Rp165.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp33.000 × 5 = Rp165.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp6.600","Rp187.000","Rp154.000","Rp176.000","Rp165.000"],"s":[0,0,0,0,1],"w":["Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Ini harga 17 roti, bukan 15.","Kurang satu barang.","Kelebihan satu barang.","Benar. Langkahnya ada di pembahasan."],"h":"Cari harga satu roti dulu: bagi Rp33.000 dengan 3."},{"i":1851,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 8 buku tulis adalah Rp28.000. Dengan harga satuan yang sama, harga 20 buku tulis adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu buku tulis = Rp28.000 ÷ 8 = Rp3.500.\n2. Harga 20 buku tulis = 20 × Rp3.500 = Rp70.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp28.000 × 2,5 = Rp70.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp70.000","Rp66.500","Rp11.200","Rp73.500","Rp77.000"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Kurang satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Kelebihan satu barang.","Ini harga 22 buku tulis, bukan 20."],"h":"Cari harga satu buku tulis dulu: bagi Rp28.000 dengan 8."},{"i":1852,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 8 cm. Skala peta 1 : 1.500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 8 × 1.500.000 = 12.000.000 cm.\n2. 1 km = 100.000 cm, jadi 12.000.000 ÷ 100.000 = 120 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.500.000 berarti 1 cm di peta = 15 km, jadi 8 × 15 = 120 km.","o":["1.200","115","12","120","125"],"s":[0,0,0,1,0],"w":["Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 115 km ÷ 15 km per cm = 23/3 cm di peta, padahal jaraknya 8 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Benar. Langkahnya ada di pembahasan.","Cek balik: 125 km ÷ 15 km per cm = 25/3 cm di peta, padahal jaraknya 8 cm."],"h":"Hapus lima angka nol dari skala: 1 : 1.500.000 berarti 1 cm di peta mewakili 15 km."},{"i":1854,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 90 km dalam 2 jam. Dengan kecepatan yang sama, jarak 180 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 90 km ÷ 2 jam = 45 km/jam.\n2. Waktu = jarak ÷ kecepatan = 180 ÷ 45 = 4 jam.\nCara cepat: bandingkan jaraknya. 180 km adalah 2 kali 90 km, jadi waktunya 2 × 2 = 4 jam.","o":["4","4,5","1","3,5","5"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 4,5 jam × 45 km/jam = 202,5 km, padahal jaraknya 180 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 3,5 jam × 45 km/jam = 157,5 km, padahal jaraknya 180 km.","Cek balik: 5 jam × 45 km/jam = 225 km, padahal jaraknya 180 km."],"h":"Cari kecepatannya dulu: 90 km dibagi 2 jam."},{"i":1855,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 2 cm. Skala peta 1 : 500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 2 × 500.000 = 1.000.000 cm.\n2. 1 km = 100.000 cm, jadi 1.000.000 ÷ 100.000 = 10 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 500.000 berarti 1 cm di peta = 5 km, jadi 2 × 5 = 10 km.","o":["100","15","1","5","10"],"s":[0,0,0,0,1],"w":["Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 15 km ÷ 5 km per cm = 3 cm di peta, padahal jaraknya 2 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 5 km ÷ 5 km per cm = 1 cm di peta, padahal jaraknya 2 cm.","Benar. Langkahnya ada di pembahasan."],"h":"Hapus lima angka nol dari skala: 1 : 500.000 berarti 1 cm di peta mewakili 5 km."},{"i":1856,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 10 orang dalam 24 hari. Jika dikerjakan 16 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 10 orang × 24 hari = 240 hari-orang.\n2. Dengan 16 orang: 240 ÷ 16 = 15 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 10 × 24 = 16 × x, jadi x = 240 ÷ 16 = 15.","o":["15","17","38,4","14","16"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 16 orang × 17 hari = 272 hari-orang, padahal beban kerjanya 240 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 16 orang × 14 hari = 224 hari-orang, padahal beban kerjanya 240 hari-orang.","Cek balik: 16 orang × 16 hari = 256 hari-orang, padahal beban kerjanya 240 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1857,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 24 orang dalam 15 hari. Jika dikerjakan 3 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 24 orang × 15 hari = 360 hari-orang.\n2. Dengan 3 orang: 360 ÷ 3 = 120 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 24 × 15 = 3 × x, jadi x = 360 ÷ 3 = 120.","o":["122","119","118","120","121"],"s":[0,0,0,1,0],"w":["Cek balik: 3 orang × 122 hari = 366 hari-orang, padahal beban kerjanya 360 hari-orang.","Cek balik: 3 orang × 119 hari = 357 hari-orang, padahal beban kerjanya 360 hari-orang.","Cek balik: 3 orang × 118 hari = 354 hari-orang, padahal beban kerjanya 360 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 3 orang × 121 hari = 363 hari-orang, padahal beban kerjanya 360 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1858,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 3 buku tulis adalah Rp13.500. Dengan harga satuan yang sama, harga 30 buku tulis adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu buku tulis = Rp13.500 ÷ 3 = Rp4.500.\n2. Harga 30 buku tulis = 30 × Rp4.500 = Rp135.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp13.500 × 10 = Rp135.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp1.350","Rp144.000","Rp130.500","Rp139.500","Rp135.000"],"s":[0,0,0,0,1],"w":["Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Ini harga 32 buku tulis, bukan 30.","Kurang satu barang.","Kelebihan satu barang.","Benar. Langkahnya ada di pembahasan."],"h":"Cari harga satu buku tulis dulu: bagi Rp13.500 dengan 3."},{"i":1859,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 16 orang dalam 40 hari. Jika dikerjakan 32 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 16 orang × 40 hari = 640 hari-orang.\n2. Dengan 32 orang: 640 ÷ 32 = 20 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 16 × 40 = 32 × x, jadi x = 640 ÷ 32 = 20.","o":["21","19","22","80","20"],"s":[0,0,0,0,1],"w":["Cek balik: 32 orang × 21 hari = 672 hari-orang, padahal beban kerjanya 640 hari-orang.","Cek balik: 32 orang × 19 hari = 608 hari-orang, padahal beban kerjanya 640 hari-orang.","Cek balik: 32 orang × 22 hari = 704 hari-orang, padahal beban kerjanya 640 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1861,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 135 km dalam 3 jam. Dengan kecepatan yang sama, jarak 180 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 135 km ÷ 3 jam = 45 km/jam.\n2. Waktu = jarak ÷ kecepatan = 180 ÷ 45 = 4 jam.\nCara cepat: bandingkan jaraknya. 180 km adalah 4/3 kali 135 km, jadi waktunya 4/3 × 3 = 4 jam.","o":["5","4","3,5","4,5","2,25"],"s":[0,1,0,0,0],"w":["Cek balik: 5 jam × 45 km/jam = 225 km, padahal jaraknya 180 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 3,5 jam × 45 km/jam = 157,5 km, padahal jaraknya 180 km.","Cek balik: 4,5 jam × 45 km/jam = 202,5 km, padahal jaraknya 180 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai."],"h":"Cari kecepatannya dulu: 135 km dibagi 3 jam."},{"i":1862,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 300 km dalam 5 jam. Dengan kecepatan yang sama, jarak 180 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 300 km ÷ 5 jam = 60 km/jam.\n2. Waktu = jarak ÷ kecepatan = 180 ÷ 60 = 3 jam.\nCara cepat: bandingkan jaraknya. 180 km adalah 0,6 kali 300 km, jadi waktunya 0,6 × 5 = 3 jam.","o":["2,5","4","3","2","3,5"],"s":[0,0,1,0,0],"w":["Cek balik: 2,5 jam × 60 km/jam = 150 km, padahal jaraknya 180 km.","Cek balik: 4 jam × 60 km/jam = 240 km, padahal jaraknya 180 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 2 jam × 60 km/jam = 120 km, padahal jaraknya 180 km.","Cek balik: 3,5 jam × 60 km/jam = 210 km, padahal jaraknya 180 km."],"h":"Cari kecepatannya dulu: 300 km dibagi 5 jam."},{"i":1863,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 7 kotak susu adalah Rp63.000. Dengan harga satuan yang sama, harga 29 kotak susu adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kotak susu = Rp63.000 ÷ 7 = Rp9.000.\n2. Harga 29 kotak susu = 29 × Rp9.000 = Rp261.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp63.000 × 29/7 = Rp261.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp243.000","Rp270.000","Rp279.000","Rp252.000","Rp261.000"],"s":[0,0,0,0,1],"w":["Ini harga 27 kotak susu, bukan 29.","Kelebihan satu barang.","Ini harga 31 kotak susu, bukan 29.","Kurang satu barang.","Benar. Langkahnya ada di pembahasan."],"h":"Cari harga satu kotak susu dulu: bagi Rp63.000 dengan 7."},{"i":1864,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 12 bungkus nasi adalah Rp300.000. Dengan harga satuan yang sama, harga 8 bungkus nasi adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu bungkus nasi = Rp300.000 ÷ 12 = Rp25.000.\n2. Harga 8 bungkus nasi = 8 × Rp25.000 = Rp200.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp300.000 × 2/3 = Rp200.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp175.000","Rp225.000","Rp450.000","Rp250.000","Rp200.000"],"s":[0,0,0,0,1],"w":["Kurang satu barang.","Kelebihan satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Ini harga 10 bungkus nasi, bukan 8.","Benar. Langkahnya ada di pembahasan."],"h":"Cari harga satu bungkus nasi dulu: bagi Rp300.000 dengan 12."},{"i":1865,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 225 km dalam 5 jam. Dengan kecepatan yang sama, jarak 180 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 225 km ÷ 5 jam = 45 km/jam.\n2. Waktu = jarak ÷ kecepatan = 180 ÷ 45 = 4 jam.\nCara cepat: bandingkan jaraknya. 180 km adalah 0,8 kali 225 km, jadi waktunya 0,8 × 5 = 4 jam.","o":["4,5","5","4","6,25","3,5"],"s":[0,0,1,0,0],"w":["Cek balik: 4,5 jam × 45 km/jam = 202,5 km, padahal jaraknya 180 km.","Cek balik: 5 jam × 45 km/jam = 225 km, padahal jaraknya 180 km.","Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 3,5 jam × 45 km/jam = 157,5 km, padahal jaraknya 180 km."],"h":"Cari kecepatannya dulu: 225 km dibagi 5 jam."},{"i":1867,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 30 orang dalam 6 hari. Jika dikerjakan 12 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 30 orang × 6 hari = 180 hari-orang.\n2. Dengan 12 orang: 180 ÷ 12 = 15 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 30 × 6 = 12 × x, jadi x = 180 ÷ 12 = 15.","o":["14","2,4","17","15","16"],"s":[0,0,0,1,0],"w":["Cek balik: 12 orang × 14 hari = 168 hari-orang, padahal beban kerjanya 180 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 12 orang × 17 hari = 204 hari-orang, padahal beban kerjanya 180 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 12 orang × 16 hari = 192 hari-orang, padahal beban kerjanya 180 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1868,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 6 botol air mineral adalah Rp18.000. Dengan harga satuan yang sama, harga 16 botol air mineral adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu botol air mineral = Rp18.000 ÷ 6 = Rp3.000.\n2. Harga 16 botol air mineral = 16 × Rp3.000 = Rp48.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp18.000 × 8/3 = Rp48.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp51.000","Rp48.000","Rp54.000","Rp45.000","Rp6.750"],"s":[0,1,0,0,0],"w":["Kelebihan satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 18 botol air mineral, bukan 16.","Kurang satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai."],"h":"Cari harga satu botol air mineral dulu: bagi Rp18.000 dengan 6."},{"i":1869,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 240 km dalam 3 jam. Dengan kecepatan yang sama, jarak 160 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 240 km ÷ 3 jam = 80 km/jam.\n2. Waktu = jarak ÷ kecepatan = 160 ÷ 80 = 2 jam.\nCara cepat: bandingkan jaraknya. 160 km adalah 2/3 kali 240 km, jadi waktunya 2/3 × 3 = 2 jam.","o":["2,5","3","1,5","2","4,5"],"s":[0,0,0,1,0],"w":["Cek balik: 2,5 jam × 80 km/jam = 200 km, padahal jaraknya 160 km.","Cek balik: 3 jam × 80 km/jam = 240 km, padahal jaraknya 160 km.","Cek balik: 1,5 jam × 80 km/jam = 120 km, padahal jaraknya 160 km.","Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai."],"h":"Cari kecepatannya dulu: 240 km dibagi 3 jam."},{"i":1870,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 11 botol air mineral adalah Rp44.000. Dengan harga satuan yang sama, harga 28 botol air mineral adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu botol air mineral = Rp44.000 ÷ 11 = Rp4.000.\n2. Harga 28 botol air mineral = 28 × Rp4.000 = Rp112.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp44.000 × 28/11 = Rp112.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp112.000","Rp104.000","Rp120.000","Rp108.000","Rp116.000"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Ini harga 26 botol air mineral, bukan 28.","Ini harga 30 botol air mineral, bukan 28.","Kurang satu barang.","Kelebihan satu barang."],"h":"Cari harga satu botol air mineral dulu: bagi Rp44.000 dengan 11."},{"i":1871,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 120 km dalam 3 jam. Dengan kecepatan yang sama, jarak 200 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 120 km ÷ 3 jam = 40 km/jam.\n2. Waktu = jarak ÷ kecepatan = 200 ÷ 40 = 5 jam.\nCara cepat: bandingkan jaraknya. 200 km adalah 5/3 kali 120 km, jadi waktunya 5/3 × 3 = 5 jam.","o":["5","4,5","5,5","6","1,8"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 4,5 jam × 40 km/jam = 180 km, padahal jaraknya 200 km.","Cek balik: 5,5 jam × 40 km/jam = 220 km, padahal jaraknya 200 km.","Cek balik: 6 jam × 40 km/jam = 240 km, padahal jaraknya 200 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai."],"h":"Cari kecepatannya dulu: 120 km dibagi 3 jam."},{"i":1872,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 27 orang dalam 40 hari. Jika dikerjakan 8 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 27 orang × 40 hari = 1080 hari-orang.\n2. Dengan 8 orang: 1080 ÷ 8 = 135 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 27 × 40 = 8 × x, jadi x = 1080 ÷ 8 = 135.","o":["133","135","136","134","137"],"s":[0,1,0,0,0],"w":["Cek balik: 8 orang × 133 hari = 1.064 hari-orang, padahal beban kerjanya 1080 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 8 orang × 136 hari = 1.088 hari-orang, padahal beban kerjanya 1080 hari-orang.","Cek balik: 8 orang × 134 hari = 1.072 hari-orang, padahal beban kerjanya 1080 hari-orang.","Cek balik: 8 orang × 137 hari = 1.096 hari-orang, padahal beban kerjanya 1080 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1873,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 450 km dalam 5 jam. Dengan kecepatan yang sama, jarak 270 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 450 km ÷ 5 jam = 90 km/jam.\n2. Waktu = jarak ÷ kecepatan = 270 ÷ 90 = 3 jam.\nCara cepat: bandingkan jaraknya. 270 km adalah 0,6 kali 450 km, jadi waktunya 0,6 × 5 = 3 jam.","o":["3,5","2,5","2","4","3"],"s":[0,0,0,0,1],"w":["Cek balik: 3,5 jam × 90 km/jam = 315 km, padahal jaraknya 270 km.","Cek balik: 2,5 jam × 90 km/jam = 225 km, padahal jaraknya 270 km.","Cek balik: 2 jam × 90 km/jam = 180 km, padahal jaraknya 270 km.","Cek balik: 4 jam × 90 km/jam = 360 km, padahal jaraknya 270 km.","Benar. Langkahnya ada di pembahasan."],"h":"Cari kecepatannya dulu: 450 km dibagi 5 jam."},{"i":1874,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 3 botol air mineral adalah Rp15.000. Dengan harga satuan yang sama, harga 6 botol air mineral adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu botol air mineral = Rp15.000 ÷ 3 = Rp5.000.\n2. Harga 6 botol air mineral = 6 × Rp5.000 = Rp30.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp15.000 × 2 = Rp30.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp25.000","Rp40.000","Rp30.000","Rp7.500","Rp35.000"],"s":[0,0,1,0,0],"w":["Kurang satu barang.","Ini harga 8 botol air mineral, bukan 6.","Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Kelebihan satu barang."],"h":"Cari harga satu botol air mineral dulu: bagi Rp15.000 dengan 3."},{"i":1875,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 4,5 cm. Skala peta 1 : 500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 4,5 × 500.000 = 2.250.000 cm.\n2. 1 km = 100.000 cm, jadi 2.250.000 ÷ 100.000 = 22,5 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 500.000 berarti 1 cm di peta = 5 km, jadi 4,5 × 5 = 22,5 km.","o":["2,25","22,5","17,5","27,5","225"],"s":[0,1,0,0,0],"w":["Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Benar. Langkahnya ada di pembahasan.","Cek balik: 17,5 km ÷ 5 km per cm = 3,5 cm di peta, padahal jaraknya 4,5 cm.","Cek balik: 27,5 km ÷ 5 km per cm = 5,5 cm di peta, padahal jaraknya 4,5 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000."],"h":"Hapus lima angka nol dari skala: 1 : 500.000 berarti 1 cm di peta mewakili 5 km."},{"i":1876,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 18 orang dalam 16 hari. Jika dikerjakan 16 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 18 orang × 16 hari = 288 hari-orang.\n2. Dengan 16 orang: 288 ÷ 16 = 18 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 18 × 16 = 16 × x, jadi x = 288 ÷ 16 = 18.","o":["17","16","19","20","18"],"s":[0,0,0,0,1],"w":["Cek balik: 16 orang × 17 hari = 272 hari-orang, padahal beban kerjanya 288 hari-orang.","Cek balik: 16 orang × 16 hari = 256 hari-orang, padahal beban kerjanya 288 hari-orang.","Cek balik: 16 orang × 19 hari = 304 hari-orang, padahal beban kerjanya 288 hari-orang.","Cek balik: 16 orang × 20 hari = 320 hari-orang, padahal beban kerjanya 288 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1878,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 27 orang dalam 40 hari. Jika dikerjakan 3 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 27 orang × 40 hari = 1080 hari-orang.\n2. Dengan 3 orang: 1080 ÷ 3 = 360 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 27 × 40 = 3 × x, jadi x = 1080 ÷ 3 = 360.","o":["362","360","358","359","361"],"s":[0,1,0,0,0],"w":["Cek balik: 3 orang × 362 hari = 1.086 hari-orang, padahal beban kerjanya 1080 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 3 orang × 358 hari = 1.074 hari-orang, padahal beban kerjanya 1080 hari-orang.","Cek balik: 3 orang × 359 hari = 1.077 hari-orang, padahal beban kerjanya 1080 hari-orang.","Cek balik: 3 orang × 361 hari = 1.083 hari-orang, padahal beban kerjanya 1080 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1880,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 2 pulpen adalah Rp5.000. Dengan harga satuan yang sama, harga 10 pulpen adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu pulpen = Rp5.000 ÷ 2 = Rp2.500.\n2. Harga 10 pulpen = 10 × Rp2.500 = Rp25.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp5.000 × 5 = Rp25.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp22.500","Rp1.000","Rp27.500","Rp25.000","Rp30.000"],"s":[0,0,0,1,0],"w":["Kurang satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Kelebihan satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 12 pulpen, bukan 10."],"h":"Cari harga satu pulpen dulu: bagi Rp5.000 dengan 2."},{"i":1881,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 150 km dalam 3 jam. Dengan kecepatan yang sama, jarak 300 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 150 km ÷ 3 jam = 50 km/jam.\n2. Waktu = jarak ÷ kecepatan = 300 ÷ 50 = 6 jam.\nCara cepat: bandingkan jaraknya. 300 km adalah 2 kali 150 km, jadi waktunya 2 × 3 = 6 jam.","o":["5,5","1,5","6,5","6","7"],"s":[0,0,0,1,0],"w":["Cek balik: 5,5 jam × 50 km/jam = 275 km, padahal jaraknya 300 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 6,5 jam × 50 km/jam = 325 km, padahal jaraknya 300 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 7 jam × 50 km/jam = 350 km, padahal jaraknya 300 km."],"h":"Cari kecepatannya dulu: 150 km dibagi 3 jam."},{"i":1882,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 240 km dalam 3 jam. Dengan kecepatan yang sama, jarak 120 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 240 km ÷ 3 jam = 80 km/jam.\n2. Waktu = jarak ÷ kecepatan = 120 ÷ 80 = 1,5 jam.\nCara cepat: bandingkan jaraknya. 120 km adalah 0,5 kali 240 km, jadi waktunya 0,5 × 3 = 1,5 jam.","o":["6","2,5","1,5","1","2"],"s":[0,0,1,0,0],"w":["Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 2,5 jam × 80 km/jam = 200 km, padahal jaraknya 120 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 1 jam × 80 km/jam = 80 km, padahal jaraknya 120 km.","Cek balik: 2 jam × 80 km/jam = 160 km, padahal jaraknya 120 km."],"h":"Cari kecepatannya dulu: 240 km dibagi 3 jam."},{"i":1884,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 30 orang dalam 6 hari. Jika dikerjakan 20 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 30 orang × 6 hari = 180 hari-orang.\n2. Dengan 20 orang: 180 ÷ 20 = 9 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 30 × 6 = 20 × x, jadi x = 180 ÷ 20 = 9.","o":["8","11","9","10","4"],"s":[0,0,1,0,0],"w":["Cek balik: 20 orang × 8 hari = 160 hari-orang, padahal beban kerjanya 180 hari-orang.","Cek balik: 20 orang × 11 hari = 220 hari-orang, padahal beban kerjanya 180 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 20 orang × 10 hari = 200 hari-orang, padahal beban kerjanya 180 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1885,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 18 orang dalam 35 hari. Jika dikerjakan 15 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 18 orang × 35 hari = 630 hari-orang.\n2. Dengan 15 orang: 630 ÷ 15 = 42 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 18 × 35 = 15 × x, jadi x = 630 ÷ 15 = 42.","o":["44","41","43","42","40"],"s":[0,0,0,1,0],"w":["Cek balik: 15 orang × 44 hari = 660 hari-orang, padahal beban kerjanya 630 hari-orang.","Cek balik: 15 orang × 41 hari = 615 hari-orang, padahal beban kerjanya 630 hari-orang.","Cek balik: 15 orang × 43 hari = 645 hari-orang, padahal beban kerjanya 630 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 15 orang × 40 hari = 600 hari-orang, padahal beban kerjanya 630 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1886,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 100 km dalam 2 jam. Dengan kecepatan yang sama, jarak 250 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 100 km ÷ 2 jam = 50 km/jam.\n2. Waktu = jarak ÷ kecepatan = 250 ÷ 50 = 5 jam.\nCara cepat: bandingkan jaraknya. 250 km adalah 2,5 kali 100 km, jadi waktunya 2,5 × 2 = 5 jam.","o":["5,5","5","4,5","0,8","6"],"s":[0,1,0,0,0],"w":["Cek balik: 5,5 jam × 50 km/jam = 275 km, padahal jaraknya 250 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 4,5 jam × 50 km/jam = 225 km, padahal jaraknya 250 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 6 jam × 50 km/jam = 300 km, padahal jaraknya 250 km."],"h":"Cari kecepatannya dulu: 100 km dibagi 2 jam."},{"i":1887,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 120 km dalam 3 jam. Dengan kecepatan yang sama, jarak 100 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 120 km ÷ 3 jam = 40 km/jam.\n2. Waktu = jarak ÷ kecepatan = 100 ÷ 40 = 2,5 jam.\nCara cepat: bandingkan jaraknya. 100 km adalah 5/6 kali 120 km, jadi waktunya 5/6 × 3 = 2,5 jam.","o":["3","3,5","3,6","2,5","2"],"s":[0,0,0,1,0],"w":["Cek balik: 3 jam × 40 km/jam = 120 km, padahal jaraknya 100 km.","Cek balik: 3,5 jam × 40 km/jam = 140 km, padahal jaraknya 100 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Benar. Langkahnya ada di pembahasan.","Cek balik: 2 jam × 40 km/jam = 80 km, padahal jaraknya 100 km."],"h":"Cari kecepatannya dulu: 120 km dibagi 3 jam."},{"i":1889,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 14 orang dalam 36 hari. Jika dikerjakan 4 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 14 orang × 36 hari = 504 hari-orang.\n2. Dengan 4 orang: 504 ÷ 4 = 126 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 14 × 36 = 4 × x, jadi x = 504 ÷ 4 = 126.","o":["124","127","128","125","126"],"s":[0,0,0,0,1],"w":["Cek balik: 4 orang × 124 hari = 496 hari-orang, padahal beban kerjanya 504 hari-orang.","Cek balik: 4 orang × 127 hari = 508 hari-orang, padahal beban kerjanya 504 hari-orang.","Cek balik: 4 orang × 128 hari = 512 hari-orang, padahal beban kerjanya 504 hari-orang.","Cek balik: 4 orang × 125 hari = 500 hari-orang, padahal beban kerjanya 504 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1890,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 8 buku tulis adalah Rp44.000. Dengan harga satuan yang sama, harga 5 buku tulis adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu buku tulis = Rp44.000 ÷ 8 = Rp5.500.\n2. Harga 5 buku tulis = 5 × Rp5.500 = Rp27.500.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp44.000 × 0,625 = Rp27.500. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp38.500","Rp33.000","Rp22.000","Rp70.400","Rp27.500"],"s":[0,0,0,0,1],"w":["Ini harga 7 buku tulis, bukan 5.","Kelebihan satu barang.","Kurang satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Benar. Langkahnya ada di pembahasan."],"h":"Cari harga satu buku tulis dulu: bagi Rp44.000 dengan 8."},{"i":1891,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 200 km dalam 5 jam. Dengan kecepatan yang sama, jarak 240 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 200 km ÷ 5 jam = 40 km/jam.\n2. Waktu = jarak ÷ kecepatan = 240 ÷ 40 = 6 jam.\nCara cepat: bandingkan jaraknya. 240 km adalah 1,2 kali 200 km, jadi waktunya 1,2 × 5 = 6 jam.","o":["7","5","6,5","6","5,5"],"s":[0,0,0,1,0],"w":["Cek balik: 7 jam × 40 km/jam = 280 km, padahal jaraknya 240 km.","Cek balik: 5 jam × 40 km/jam = 200 km, padahal jaraknya 240 km.","Cek balik: 6,5 jam × 40 km/jam = 260 km, padahal jaraknya 240 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 5,5 jam × 40 km/jam = 220 km, padahal jaraknya 240 km."],"h":"Cari kecepatannya dulu: 200 km dibagi 5 jam."},{"i":1892,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 360 km dalam 4 jam. Dengan kecepatan yang sama, jarak 180 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 360 km ÷ 4 jam = 90 km/jam.\n2. Waktu = jarak ÷ kecepatan = 180 ÷ 90 = 2 jam.\nCara cepat: bandingkan jaraknya. 180 km adalah 0,5 kali 360 km, jadi waktunya 0,5 × 4 = 2 jam.","o":["3","2,5","2","8","1,5"],"s":[0,0,1,0,0],"w":["Cek balik: 3 jam × 90 km/jam = 270 km, padahal jaraknya 180 km.","Cek balik: 2,5 jam × 90 km/jam = 225 km, padahal jaraknya 180 km.","Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 1,5 jam × 90 km/jam = 135 km, padahal jaraknya 180 km."],"h":"Cari kecepatannya dulu: 360 km dibagi 4 jam."},{"i":1893,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 6 bungkus nasi adalah Rp90.000. Dengan harga satuan yang sama, harga 11 bungkus nasi adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu bungkus nasi = Rp90.000 ÷ 6 = Rp15.000.\n2. Harga 11 bungkus nasi = 11 × Rp15.000 = Rp165.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp90.000 × 11/6 = Rp165.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp135.000","Rp195.000","Rp165.000","Rp150.000","Rp180.000"],"s":[0,0,1,0,0],"w":["Ini harga 9 bungkus nasi, bukan 11.","Ini harga 13 bungkus nasi, bukan 11.","Benar. Langkahnya ada di pembahasan.","Kurang satu barang.","Kelebihan satu barang."],"h":"Cari harga satu bungkus nasi dulu: bagi Rp90.000 dengan 6."},{"i":1894,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 21 orang dalam 40 hari. Jika dikerjakan 4 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 21 orang × 40 hari = 840 hari-orang.\n2. Dengan 4 orang: 840 ÷ 4 = 210 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 21 × 40 = 4 × x, jadi x = 840 ÷ 4 = 210.","o":["211","208","210","212","209"],"s":[0,0,1,0,0],"w":["Cek balik: 4 orang × 211 hari = 844 hari-orang, padahal beban kerjanya 840 hari-orang.","Cek balik: 4 orang × 208 hari = 832 hari-orang, padahal beban kerjanya 840 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 4 orang × 212 hari = 848 hari-orang, padahal beban kerjanya 840 hari-orang.","Cek balik: 4 orang × 209 hari = 836 hari-orang, padahal beban kerjanya 840 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1896,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 4 buku tulis adalah Rp30.000. Dengan harga satuan yang sama, harga 22 buku tulis adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu buku tulis = Rp30.000 ÷ 4 = Rp7.500.\n2. Harga 22 buku tulis = 22 × Rp7.500 = Rp165.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp30.000 × 5,5 = Rp165.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp180.000","Rp172.500","Rp165.000","Rp150.000","Rp157.500"],"s":[0,0,1,0,0],"w":["Ini harga 24 buku tulis, bukan 22.","Kelebihan satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 20 buku tulis, bukan 22.","Kurang satu barang."],"h":"Cari harga satu buku tulis dulu: bagi Rp30.000 dengan 4."},{"i":1897,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 2 botol air mineral adalah Rp12.000. Dengan harga satuan yang sama, harga 8 botol air mineral adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu botol air mineral = Rp12.000 ÷ 2 = Rp6.000.\n2. Harga 8 botol air mineral = 8 × Rp6.000 = Rp48.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp12.000 × 4 = Rp48.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp3.000","Rp42.000","Rp54.000","Rp48.000","Rp60.000"],"s":[0,0,0,1,0],"w":["Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Kurang satu barang.","Kelebihan satu barang.","Benar. Langkahnya ada di pembahasan.","Ini harga 10 botol air mineral, bukan 8."],"h":"Cari harga satu botol air mineral dulu: bagi Rp12.000 dengan 2."},{"i":1898,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 250 km dalam 5 jam. Dengan kecepatan yang sama, jarak 300 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 250 km ÷ 5 jam = 50 km/jam.\n2. Waktu = jarak ÷ kecepatan = 300 ÷ 50 = 6 jam.\nCara cepat: bandingkan jaraknya. 300 km adalah 1,2 kali 250 km, jadi waktunya 1,2 × 5 = 6 jam.","o":["5","6,5","5,5","6","7"],"s":[0,0,0,1,0],"w":["Cek balik: 5 jam × 50 km/jam = 250 km, padahal jaraknya 300 km.","Cek balik: 6,5 jam × 50 km/jam = 325 km, padahal jaraknya 300 km.","Cek balik: 5,5 jam × 50 km/jam = 275 km, padahal jaraknya 300 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 7 jam × 50 km/jam = 350 km, padahal jaraknya 300 km."],"h":"Cari kecepatannya dulu: 250 km dibagi 5 jam."},{"i":1899,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 9 orang dalam 26 hari. Jika dikerjakan 39 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 9 orang × 26 hari = 234 hari-orang.\n2. Dengan 39 orang: 234 ÷ 39 = 6 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 9 × 26 = 39 × x, jadi x = 234 ÷ 39 = 6.","o":["6","7","4","5","8"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 39 orang × 7 hari = 273 hari-orang, padahal beban kerjanya 234 hari-orang.","Cek balik: 39 orang × 4 hari = 156 hari-orang, padahal beban kerjanya 234 hari-orang.","Cek balik: 39 orang × 5 hari = 195 hari-orang, padahal beban kerjanya 234 hari-orang.","Cek balik: 39 orang × 8 hari = 312 hari-orang, padahal beban kerjanya 234 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1901,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 21 orang dalam 33 hari. Jika dikerjakan 9 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 21 orang × 33 hari = 693 hari-orang.\n2. Dengan 9 orang: 693 ÷ 9 = 77 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 21 × 33 = 9 × x, jadi x = 693 ÷ 9 = 77.","o":["76","75","77","78","79"],"s":[0,0,1,0,0],"w":["Cek balik: 9 orang × 76 hari = 684 hari-orang, padahal beban kerjanya 693 hari-orang.","Cek balik: 9 orang × 75 hari = 675 hari-orang, padahal beban kerjanya 693 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 9 orang × 78 hari = 702 hari-orang, padahal beban kerjanya 693 hari-orang.","Cek balik: 9 orang × 79 hari = 711 hari-orang, padahal beban kerjanya 693 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1902,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 7,5 cm. Skala peta 1 : 1.500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 7,5 × 1.500.000 = 11.250.000 cm.\n2. 1 km = 100.000 cm, jadi 11.250.000 ÷ 100.000 = 112,5 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.500.000 berarti 1 cm di peta = 15 km, jadi 7,5 × 15 = 112,5 km.","o":["11,25","1.125","117,5","107,5","112,5"],"s":[0,0,0,0,1],"w":["Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 117,5 km ÷ 15 km per cm = 47/6 cm di peta, padahal jaraknya 7,5 cm.","Cek balik: 107,5 km ÷ 15 km per cm = 43/6 cm di peta, padahal jaraknya 7,5 cm.","Benar. Langkahnya ada di pembahasan."],"h":"Hapus lima angka nol dari skala: 1 : 1.500.000 berarti 1 cm di peta mewakili 15 km."},{"i":1904,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 320 km dalam 4 jam. Dengan kecepatan yang sama, jarak 400 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 320 km ÷ 4 jam = 80 km/jam.\n2. Waktu = jarak ÷ kecepatan = 400 ÷ 80 = 5 jam.\nCara cepat: bandingkan jaraknya. 400 km adalah 1,25 kali 320 km, jadi waktunya 1,25 × 4 = 5 jam.","o":["4,5","5,5","6","5","3,2"],"s":[0,0,0,1,0],"w":["Cek balik: 4,5 jam × 80 km/jam = 360 km, padahal jaraknya 400 km.","Cek balik: 5,5 jam × 80 km/jam = 440 km, padahal jaraknya 400 km.","Cek balik: 6 jam × 80 km/jam = 480 km, padahal jaraknya 400 km.","Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai."],"h":"Cari kecepatannya dulu: 320 km dibagi 4 jam."},{"i":1905,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 6 orang dalam 32 hari. Jika dikerjakan 24 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 6 orang × 32 hari = 192 hari-orang.\n2. Dengan 24 orang: 192 ÷ 24 = 8 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 6 × 32 = 24 × x, jadi x = 192 ÷ 24 = 8.","o":["9","8","7","10","128"],"s":[0,1,0,0,0],"w":["Cek balik: 24 orang × 9 hari = 216 hari-orang, padahal beban kerjanya 192 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 24 orang × 7 hari = 168 hari-orang, padahal beban kerjanya 192 hari-orang.","Cek balik: 24 orang × 10 hari = 240 hari-orang, padahal beban kerjanya 192 hari-orang.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1909,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 29 orang dalam 30 hari. Jika dikerjakan 10 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 29 orang × 30 hari = 870 hari-orang.\n2. Dengan 10 orang: 870 ÷ 10 = 87 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 29 × 30 = 10 × x, jadi x = 870 ÷ 10 = 87.","o":["86","89","88","85","87"],"s":[0,0,0,0,1],"w":["Cek balik: 10 orang × 86 hari = 860 hari-orang, padahal beban kerjanya 870 hari-orang.","Cek balik: 10 orang × 89 hari = 890 hari-orang, padahal beban kerjanya 870 hari-orang.","Cek balik: 10 orang × 88 hari = 880 hari-orang, padahal beban kerjanya 870 hari-orang.","Cek balik: 10 orang × 85 hari = 850 hari-orang, padahal beban kerjanya 870 hari-orang.","Benar. Langkahnya ada di pembahasan."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1910,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 240 km dalam 3 jam. Dengan kecepatan yang sama, jarak 480 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 240 km ÷ 3 jam = 80 km/jam.\n2. Waktu = jarak ÷ kecepatan = 480 ÷ 80 = 6 jam.\nCara cepat: bandingkan jaraknya. 480 km adalah 2 kali 240 km, jadi waktunya 2 × 3 = 6 jam.","o":["7","1,5","6,5","5,5","6"],"s":[0,0,0,0,1],"w":["Cek balik: 7 jam × 80 km/jam = 560 km, padahal jaraknya 480 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 6,5 jam × 80 km/jam = 520 km, padahal jaraknya 480 km.","Cek balik: 5,5 jam × 80 km/jam = 440 km, padahal jaraknya 480 km.","Benar. Langkahnya ada di pembahasan."],"h":"Cari kecepatannya dulu: 240 km dibagi 3 jam."},{"i":1912,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 6 orang dalam 40 hari. Jika dikerjakan 10 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 6 orang × 40 hari = 240 hari-orang.\n2. Dengan 10 orang: 240 ÷ 10 = 24 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 6 × 40 = 10 × x, jadi x = 240 ÷ 10 = 24.","o":["26","25","24","23","22"],"s":[0,0,1,0,0],"w":["Cek balik: 10 orang × 26 hari = 260 hari-orang, padahal beban kerjanya 240 hari-orang.","Cek balik: 10 orang × 25 hari = 250 hari-orang, padahal beban kerjanya 240 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 10 orang × 23 hari = 230 hari-orang, padahal beban kerjanya 240 hari-orang.","Cek balik: 10 orang × 22 hari = 220 hari-orang, padahal beban kerjanya 240 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1913,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 100 km dalam 2 jam. Dengan kecepatan yang sama, jarak 200 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 100 km ÷ 2 jam = 50 km/jam.\n2. Waktu = jarak ÷ kecepatan = 200 ÷ 50 = 4 jam.\nCara cepat: bandingkan jaraknya. 200 km adalah 2 kali 100 km, jadi waktunya 2 × 2 = 4 jam.","o":["5","4","4,5","3,5","1"],"s":[0,1,0,0,0],"w":["Cek balik: 5 jam × 50 km/jam = 250 km, padahal jaraknya 200 km.","Benar. Langkahnya ada di pembahasan.","Cek balik: 4,5 jam × 50 km/jam = 225 km, padahal jaraknya 200 km.","Cek balik: 3,5 jam × 50 km/jam = 175 km, padahal jaraknya 200 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai."],"h":"Cari kecepatannya dulu: 100 km dibagi 2 jam."},{"i":1915,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 3 cm. Skala peta 1 : 3.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 3 × 3.000.000 = 9.000.000 cm.\n2. 1 km = 100.000 cm, jadi 9.000.000 ÷ 100.000 = 90 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 3.000.000 berarti 1 cm di peta = 30 km, jadi 3 × 30 = 90 km.","o":["85","900","95","9","90"],"s":[0,0,0,0,1],"w":["Cek balik: 85 km ÷ 30 km per cm = 17/6 cm di peta, padahal jaraknya 3 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Cek balik: 95 km ÷ 30 km per cm = 19/6 cm di peta, padahal jaraknya 3 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Benar. Langkahnya ada di pembahasan."],"h":"Hapus lima angka nol dari skala: 1 : 3.000.000 berarti 1 cm di peta mewakili 30 km."},{"i":1916,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 20 orang dalam 18 hari. Jika dikerjakan 30 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 20 orang × 18 hari = 360 hari-orang.\n2. Dengan 30 orang: 360 ÷ 30 = 12 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 20 × 18 = 30 × x, jadi x = 360 ÷ 30 = 12.","o":["13","14","12","27","11"],"s":[0,0,1,0,0],"w":["Cek balik: 30 orang × 13 hari = 390 hari-orang, padahal beban kerjanya 360 hari-orang.","Cek balik: 30 orang × 14 hari = 420 hari-orang, padahal beban kerjanya 360 hari-orang.","Benar. Langkahnya ada di pembahasan.","Ini kalau dihitung senilai. Makin banyak orang, makin cepat selesai: perbandingannya berbalik nilai.","Cek balik: 30 orang × 11 hari = 330 hari-orang, padahal beban kerjanya 360 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1917,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Sebuah mobil menempuh 300 km dalam 5 jam. Dengan kecepatan yang sama, jarak 240 km ditempuh dalam … jam.","e":"Konsep: dengan kecepatan tetap, jarak dan waktu senilai. Jarak dua kali lipat, waktunya juga dua kali lipat.\n1. Kecepatan = 300 km ÷ 5 jam = 60 km/jam.\n2. Waktu = jarak ÷ kecepatan = 240 ÷ 60 = 4 jam.\nCara cepat: bandingkan jaraknya. 240 km adalah 0,8 kali 300 km, jadi waktunya 0,8 × 5 = 4 jam.","o":["4","4,5","6,25","3,5","5"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Cek balik: 4,5 jam × 60 km/jam = 270 km, padahal jaraknya 240 km.","Ini kalau dihitung berbalik nilai. Jarak lebih jauh butuh waktu lebih lama: senilai.","Cek balik: 3,5 jam × 60 km/jam = 210 km, padahal jaraknya 240 km.","Cek balik: 5 jam × 60 km/jam = 300 km, padahal jaraknya 240 km."],"h":"Cari kecepatannya dulu: 300 km dibagi 5 jam."},{"i":1918,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 11 orang dalam 18 hari. Jika dikerjakan 6 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 11 orang × 18 hari = 198 hari-orang.\n2. Dengan 6 orang: 198 ÷ 6 = 33 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 11 × 18 = 6 × x, jadi x = 198 ÷ 6 = 33.","o":["34","32","33","35","31"],"s":[0,0,1,0,0],"w":["Cek balik: 6 orang × 34 hari = 204 hari-orang, padahal beban kerjanya 198 hari-orang.","Cek balik: 6 orang × 32 hari = 192 hari-orang, padahal beban kerjanya 198 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 6 orang × 35 hari = 210 hari-orang, padahal beban kerjanya 198 hari-orang.","Cek balik: 6 orang × 31 hari = 186 hari-orang, padahal beban kerjanya 198 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1919,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 6 cm. Skala peta 1 : 2.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 6 × 2.000.000 = 12.000.000 cm.\n2. 1 km = 100.000 cm, jadi 12.000.000 ÷ 100.000 = 120 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 2.000.000 berarti 1 cm di peta = 20 km, jadi 6 × 20 = 120 km.","o":["115","1.200","120","12","125"],"s":[0,0,1,0,0],"w":["Cek balik: 115 km ÷ 20 km per cm = 5,75 cm di peta, padahal jaraknya 6 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000.","Benar. Langkahnya ada di pembahasan.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 125 km ÷ 20 km per cm = 6,25 cm di peta, padahal jaraknya 6 cm."],"h":"Hapus lima angka nol dari skala: 1 : 2.000.000 berarti 1 cm di peta mewakili 20 km."},{"i":1920,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 8 cm. Skala peta 1 : 3.000.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 8 × 3.000.000 = 24.000.000 cm.\n2. 1 km = 100.000 cm, jadi 24.000.000 ÷ 100.000 = 240 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 3.000.000 berarti 1 cm di peta = 30 km, jadi 8 × 30 = 240 km.","o":["240","24","245","235","2.400"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Cek balik: 245 km ÷ 30 km per cm = 49/6 cm di peta, padahal jaraknya 8 cm.","Cek balik: 235 km ÷ 30 km per cm = 47/6 cm di peta, padahal jaraknya 8 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000."],"h":"Hapus lima angka nol dari skala: 1 : 3.000.000 berarti 1 cm di peta mewakili 30 km."},{"i":1921,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 12 buku tulis adalah Rp78.000. Dengan harga satuan yang sama, harga 22 buku tulis adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu buku tulis = Rp78.000 ÷ 12 = Rp6.500.\n2. Harga 22 buku tulis = 22 × Rp6.500 = Rp143.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp78.000 × 11/6 = Rp143.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp143.000","Rp136.500","Rp149.500","Rp130.000","Rp156.000"],"s":[1,0,0,0,0],"w":["Benar. Langkahnya ada di pembahasan.","Kurang satu barang.","Kelebihan satu barang.","Ini harga 20 buku tulis, bukan 22.","Ini harga 24 buku tulis, bukan 22."],"h":"Cari harga satu buku tulis dulu: bagi Rp78.000 dengan 12."},{"i":1922,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Jarak dua kota pada peta adalah 2 cm. Skala peta 1 : 1.500.000. Jarak sebenarnya adalah … km.","e":"Konsep: jarak sebenarnya = jarak di peta × skala, lalu ubah satuannya.\n1. 2 × 1.500.000 = 3.000.000 cm.\n2. 1 km = 100.000 cm, jadi 3.000.000 ÷ 100.000 = 30 km.\nCara cepat: hapus lima angka nol dari skala. 1 : 1.500.000 berarti 1 cm di peta = 15 km, jadi 2 × 15 = 30 km.","o":["35","3","30","25","300"],"s":[0,0,1,0,0],"w":["Cek balik: 35 km ÷ 15 km per cm = 7/3 cm di peta, padahal jaraknya 2 cm.","Satuannya meleset sepuluh kali. Ingat 1 km = 100.000 cm.","Benar. Langkahnya ada di pembahasan.","Cek balik: 25 km ÷ 15 km per cm = 5/3 cm di peta, padahal jaraknya 2 cm.","Satuannya meleset. 1 km = 100.000 cm, jadi bagi dengan 100.000."],"h":"Hapus lima angka nol dari skala: 1 : 1.500.000 berarti 1 cm di peta mewakili 15 km."},{"i":1923,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 6 roti adalah Rp24.000. Dengan harga satuan yang sama, harga 21 roti adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu roti = Rp24.000 ÷ 6 = Rp4.000.\n2. Harga 21 roti = 21 × Rp4.000 = Rp84.000.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp24.000 × 3,5 = Rp84.000. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp76.000","Rp92.000","Rp84.000","Rp80.000","Rp88.000"],"s":[0,0,1,0,0],"w":["Ini harga 19 roti, bukan 21.","Ini harga 23 roti, bukan 21.","Benar. Langkahnya ada di pembahasan.","Kurang satu barang.","Kelebihan satu barang."],"h":"Cari harga satu roti dulu: bagi Rp24.000 dengan 6."},{"i":1924,"k":"skd.tiu.perbandingan","j":"pilgan","v":3,"q":"Sebuah pekerjaan dapat diselesaikan 22 orang dalam 36 hari. Jika dikerjakan 9 orang dengan kecepatan kerja yang sama, pekerjaan itu selesai dalam … hari.","e":"Konsep: makin banyak orang, makin cepat pekerjaan selesai. Ini perbandingan berbalik nilai.\n1. Beban kerjanya tetap: 22 orang × 36 hari = 792 hari-orang.\n2. Dengan 9 orang: 792 ÷ 9 = 88 hari.\nCara cepat: pada perbandingan berbalik nilai, hasil kalinya selalu tetap: 22 × 36 = 9 × x, jadi x = 792 ÷ 9 = 88.","o":["86","88","89","90","87"],"s":[0,1,0,0,0],"w":["Cek balik: 9 orang × 86 hari = 774 hari-orang, padahal beban kerjanya 792 hari-orang.","Benar. Langkahnya ada di pembahasan.","Cek balik: 9 orang × 89 hari = 801 hari-orang, padahal beban kerjanya 792 hari-orang.","Cek balik: 9 orang × 90 hari = 810 hari-orang, padahal beban kerjanya 792 hari-orang.","Cek balik: 9 orang × 87 hari = 783 hari-orang, padahal beban kerjanya 792 hari-orang."],"h":"Kalikan jumlah orang dengan jumlah harinya untuk mendapat beban kerja, lalu bagi dengan jumlah orang yang baru."},{"i":1925,"k":"skd.tiu.perbandingan","j":"pilgan","v":2,"q":"Harga 12 kotak susu adalah Rp78.000. Dengan harga satuan yang sama, harga 5 kotak susu adalah …","e":"Konsep: makin banyak barang, makin mahal harganya. Ini perbandingan senilai.\n1. Harga satu kotak susu = Rp78.000 ÷ 12 = Rp6.500.\n2. Harga 5 kotak susu = 5 × Rp6.500 = Rp32.500.\nCara cepat: kalikan langsung dengan perbandingan jumlahnya: Rp78.000 × 5/12 = Rp32.500. Kalau angkanya sulit, cari harga satuan dulu seperti langkah 1.","o":["Rp39.000","Rp187.200","Rp32.500","Rp45.500","Rp26.000"],"s":[0,0,1,0,0],"w":["Kelebihan satu barang.","Ini kalau dihitung berbalik nilai. Makin banyak barang, makin mahal: perbandingannya senilai.","Benar. Langkahnya ada di pembahasan.","Ini harga 7 kotak susu, bukan 5.","Kurang satu barang."],"h":"Cari harga satu kotak susu dulu: bagi Rp78.000 dengan 12."}];
